package cli

import (
	"context"
	"fmt"
	"os/signal"
	"path/filepath"
	stdruntime "runtime"
	"syscall"
	"time"

	"github.com/spf13/cobra"

	"syncd/internal/app"
	"syncd/internal/fs"
	"syncd/internal/watch"
)

// watchDebounce is the fsnotify batch-coalescing window. It is small enough
// that local edits still feel "instant" and isn't expected to need tuning
// per-deployment, so it is a constant rather than a flag.
const watchDebounce = 500 * time.Millisecond

var (
	watchLocal      string
	watchRemote     string
	watchRemotePoll time.Duration
	watchDeepScan   time.Duration
	watchSilent     bool
	watchWorkers    int
	watchStateDir   string
	watchDBPath     string
	watchLogPath    string
	watchLockPath   string
)

// watchCmd is the always-on daemon path of the merged tool: `syncd watch`.
// It combines an fsnotify watcher for near-instant local-change propagation
// with periodic full remote polls (catches writes made by other machines on
// the same remote) and a periodic full deep scan (catches new empty
// directories and recursively-deleted local directories, which the
// fsnotify-driven scoped reconcile can't see - see internal/watch/loop.go).
var watchCmd = &cobra.Command{
	Use:   "watch",
	Short: "Run the always-on watch daemon (local events + remote poll + deep scan)",
	Long: `Run syncd as an always-on daemon: local filesystem changes under --local are
reconciled to --remote almost immediately via an fsnotify watcher, a full
remote poll runs every --remote-poll to catch changes made directly on the
remote by another machine, and a full deep scan runs every --deep-scan as a
safety net (it is the only pass that picks up newly created empty
directories and directories deleted recursively on the local side).

Run 'syncd init --local ... --remote ...' first to bootstrap the roots and
the remote canary file.`,
	RunE: runWatchCmd,
}

func init() {
	watchCmd.Flags().StringVar(&watchLocal, "local", "", "Local directory path (required)")
	watchCmd.Flags().StringVar(&watchRemote, "remote", "", "Remote directory path (required)")
	watchCmd.Flags().DurationVar(&watchRemotePoll, "remote-poll", 30*time.Second, "Full remote poll cadence (catches other machines' remote writes)")
	watchCmd.Flags().DurationVar(&watchDeepScan, "deep-scan", time.Hour, "Full-tree deep-scan safety-net cadence")
	watchCmd.Flags().BoolVar(&watchSilent, "silent", false, "Write structured logs only, suppress stdout")
	watchCmd.Flags().IntVar(&watchWorkers, "workers", stdruntime.NumCPU(), "Worker pool size")
	watchCmd.Flags().StringVar(&watchStateDir, "state-dir", "", "State directory for lock/db/log")
	watchCmd.Flags().StringVar(&watchDBPath, "db-path", "", "Path to SQLite manifest file")
	watchCmd.Flags().StringVar(&watchLogPath, "log-path", "", "Path to JSON log file")
	watchCmd.Flags().StringVar(&watchLockPath, "lock-path", "", "Path to lock file")
	_ = watchCmd.MarkFlagRequired("local")
	_ = watchCmd.MarkFlagRequired("remote")

	rootCmd.AddCommand(watchCmd)
}

// validateWatchFlags rejects CLI-supplied watch flag values that would
// otherwise reach lower layers unchecked: workers < 1, or a non-positive
// --remote-poll/--deep-scan, which would panic time.NewTicker deep inside
// watch.Run (that library also defends on its own - see loop.go - but the
// CLI should give a clear error up front rather than let it fall through).
func validateWatchFlags(workers int, remotePoll, deepScan time.Duration) error {
	if workers < 1 {
		return fmt.Errorf("--workers must be >= 1")
	}
	if remotePoll <= 0 {
		return fmt.Errorf("--remote-poll must be > 0 (got %s)", remotePoll)
	}
	if deepScan <= 0 {
		return fmt.Errorf("--deep-scan must be > 0 (got %s)", deepScan)
	}
	return nil
}

func runWatchCmd(cmd *cobra.Command, _ []string) error {
	localAbs, err := filepath.Abs(watchLocal)
	if err != nil {
		return fmt.Errorf("resolve --local: %w", err)
	}
	remoteAbs, err := filepath.Abs(watchRemote)
	if err != nil {
		return fmt.Errorf("resolve --remote: %w", err)
	}
	if err := validateWatchFlags(watchWorkers, watchRemotePoll, watchDeepScan); err != nil {
		return err
	}

	ctx, stop := signal.NotifyContext(cmd.Context(), syscall.SIGINT, syscall.SIGTERM)
	defer stop()

	cfg := app.WatchConfig{
		LocalRoot:  localAbs,
		RemoteRoot: remoteAbs,
		Silent:     watchSilent,
		Workers:    watchWorkers,
		StateDir:   watchStateDir,
		DBPath:     watchDBPath,
		LogPath:    watchLogPath,
		LockPath:   watchLockPath,
		RemotePoll: watchRemotePoll,
		DeepScan:   watchDeepScan,
		Debounce:   watchDebounce,
	}

	return app.RunWatch(ctx, cfg, func(ctx context.Context, p app.RobustParams, matcher *fs.IgnoreMatcher, cfg app.WatchConfig) error {
		return watch.Run(ctx, p, matcher, watch.LoopConfig{
			RemotePoll: cfg.RemotePoll,
			DeepScan:   cfg.DeepScan,
			Debounce:   cfg.Debounce,
		})
	})
}
package cli

import (
	"fmt"
	"os"

	"github.com/spf13/cobra"
)

var rootCmd = &cobra.Command{
	Use:   "syncd",
	Short: "Fast ad-hoc and always-on directory synchronization",
	// Execute prints the returned error itself; without this cobra prints
	// it too, so every failure showed up twice.
	SilenceErrors: true,
	// Usage help is for mistakes in how the command was invoked (unknown
	// flag, missing required flag), which cobra reports before any
	// PersistentPreRun. Once a command actually starts running, a runtime
	// failure (missing source dir, held lock, failed copy) must not bury
	// its error under the full flag listing.
	PersistentPreRun: func(cmd *cobra.Command, _ []string) {
		cmd.SilenceUsage = true
	},
}

// Execute runs the root command; each subcommand registers itself in its own file's init().
func Execute() {
	if err := rootCmd.Execute(); err != nil {
		fmt.Fprintln(os.Stderr, err)
		os.Exit(1)
	}
}
package cli

import (
	"errors"
	"fmt"
	"os"

	"github.com/spf13/viper"
)

// SyncConfig is the structure of the batch job config file (~/.syncd.yaml)
// consumed by the `syncd sync` command when it isn't given --left/--right
// for a one-off job. Ported from file_sync_util's cmd/root.go Config/SyncJob
// (name kept distinct from the legacy runtime.Config used by the always-on
// daemon, and tags adapted for our viper setup).
type SyncConfig struct {
	Jobs []SyncJob `mapstructure:"jobs"`
}

// SyncJob is a single synchronization job entry in the batch config file.
type SyncJob struct {
	Name  string `mapstructure:"name"`
	Left  string `mapstructure:"left"`
	Right string `mapstructure:"right"`
	Mode  string `mapstructure:"mode"` // two-way, mirror, update
}

// initSyncConfig wires viper to read ~/.syncd.yaml (or the file at
// cfgFile, if set) before the sync command runs. Ported from
// file_sync_util's initConfig, adapted from .syncutil to .syncd.
//
// A ReadInConfig error is only tolerated when cfgFile is empty AND it's
// specifically "the default ~/.syncd.yaml simply doesn't exist" - ad-hoc
// --left/--right jobs don't require a config file at all, so that case must
// stay silent. Every other case (an explicit --config that's missing,
// unreadable, or malformed YAML; or a malformed default ~/.syncd.yaml) must
// surface as a real error instead of being swallowed into a misleading "no
// jobs found" later (review finding "Medium 10").
func initSyncConfig(cfgFile string) error {
	explicit := cfgFile != ""
	if explicit {
		viper.SetConfigFile(cfgFile)
	} else {
		home, err := os.UserHomeDir()
		if err != nil {
			return fmt.Errorf("resolve home directory: %w", err)
		}

		viper.AddConfigPath(home)
		viper.SetConfigType("yaml")
		viper.SetConfigName(".syncd")
	}

	viper.AutomaticEnv()

	if err := viper.ReadInConfig(); err != nil {
		var notFound viper.ConfigFileNotFoundError
		if !explicit && errors.As(err, &notFound) {
			return nil
		}
		return fmt.Errorf("read config file: %w", err)
	}
	return nil
}

// loadSyncConfig reads the batch config file (via initSyncConfig) and
// unmarshals it into a SyncConfig.
func loadSyncConfig(cfgFile string) (SyncConfig, error) {
	if err := initSyncConfig(cfgFile); err != nil {
		return SyncConfig{}, err
	}
	var cfg SyncConfig
	if err := viper.Unmarshal(&cfg); err != nil {
		return SyncConfig{}, err
	}
	return cfg, nil
}
package cli

import (
	"fmt"
	"path/filepath"

	"github.com/spf13/cobra"

	"syncd/internal/app"
	"syncd/internal/runtime"
)

var (
	initLocal  string
	initRemote string
)

// initCmd bootstraps the local/remote roots and the remote canary file used
// by the always-on sync daemon (app.Run --init). It performs no
// reconciliation; it just makes sure both directories exist and the remote
// side is marked as a valid sync target before the daemon's first real run.
var initCmd = &cobra.Command{
	Use:   "init",
	Short: "Bootstrap local/remote roots and the remote canary file for always-on sync",
	RunE:  runInitCmd,
}

func init() {
	initCmd.Flags().StringVar(&initLocal, "local", "", "Local directory path (required)")
	initCmd.Flags().StringVar(&initRemote, "remote", "", "Remote directory path (required)")
	_ = initCmd.MarkFlagRequired("local")
	_ = initCmd.MarkFlagRequired("remote")

	rootCmd.AddCommand(initCmd)
}

func runInitCmd(_ *cobra.Command, _ []string) error {
	localAbs, err := filepath.Abs(initLocal)
	if err != nil {
		return fmt.Errorf("resolve --local: %w", err)
	}
	remoteAbs, err := filepath.Abs(initRemote)
	if err != nil {
		return fmt.Errorf("resolve --remote: %w", err)
	}

	logger, err := runtime.NewLogger(false, "")
	if err != nil {
		return err
	}
	defer logger.Close()

	return app.RunInit(localAbs, remoteAbs, logger)
}
package runtime

import (
	"fmt"
	"os"
	"path/filepath"
)

// EnsureRemoteCanary creates the remote canary file if it's missing, for
// first-time setup (see --init). It reports whether it actually created the
// file so callers can log accordingly.
func EnsureRemoteCanary(remoteRoot string) (created bool, err error) {
	canaryPath := filepath.Join(remoteRoot, ".synclock")
	if _, statErr := os.Stat(canaryPath); statErr == nil {
		return false, nil
	} else if !os.IsNotExist(statErr) {
		return false, fmt.Errorf("stat remote canary: %w", statErr)
	}
	if err := os.WriteFile(canaryPath, []byte("syncd canary\n"), 0o644); err != nil {
		return false, fmt.Errorf("create remote canary: %w", err)
	}
	return true, nil
}

func CheckRemoteCanary(remoteRoot string) error {
	canaryPath := filepath.Join(remoteRoot, ".synclock")
	info, err := os.Stat(canaryPath)
	if err != nil {
		if os.IsNotExist(err) {
			return fmt.Errorf("remote canary file missing: %s", canaryPath)
		}
		return fmt.Errorf("stat remote canary: %w", err)
	}
	if info.IsDir() {
		return fmt.Errorf("remote canary path is a directory: %s", canaryPath)
	}
	return nil
}
package runtime

import (
	"fmt"
	"os"
	"syscall"
)

type Lock struct {
	file *os.File
	path string
}

func AcquireLock(path string) (*Lock, error) {
	f, err := os.OpenFile(path, os.O_CREATE|os.O_RDWR, 0o644)
	if err != nil {
		return nil, fmt.Errorf("open lock file: %w", err)
	}
	if err := syscall.Flock(int(f.Fd()), syscall.LOCK_EX|syscall.LOCK_NB); err != nil {
		_ = f.Close()
		return nil, fmt.Errorf("sync lock already held at %s", path)
	}
	return &Lock{file: f, path: path}, nil
}

func (l *Lock) Release() error {
	if l == nil || l.file == nil {
		return nil
	}
	defer func() {
		l.file = nil
	}()
	if err := syscall.Flock(int(l.file.Fd()), syscall.LOCK_UN); err != nil {
		_ = l.file.Close()
		return fmt.Errorf("unlock lock file: %w", err)
	}
	if err := l.file.Close(); err != nil {
		return fmt.Errorf("close lock file: %w", err)
	}
	return nil
}
package runtime

// Config is the legacy flags-based configuration for the always-on sync
// daemon (formerly app.Run, removed as dead code once the cobra CLI -
// cmd/syncd -> cli.Execute - superseded it). Config itself is still used by
// ResolvePaths (see paths.go) for state-dir/db/log/lock path resolution, so
// it's kept; only its ParseArgs flag parser, which had no remaining caller,
// was removed.
type Config struct {
	LocalRoot  string
	RemoteRoot string
	DryRun     bool
	Silent     bool
	Init       bool
	Workers    int
	StateDir   string
	DBPath     string
	LogPath    string
	LockPath   string
}
package app

import (
	"context"
	"fmt"
	"os"
	"path/filepath"
	"time"

	"syncd/internal/db"
	"syncd/internal/fs"
	"syncd/internal/runtime"
)

// WatchConfig configures RunWatch: the always-on, event-driven daemon
// (`syncd watch`). It mirrors runtime.Config's path/runtime-resolution
// fields (state dir / db / log / lock overrides, local+remote roots,
// worker count, silent logging) plus the watch loop's three cadences.
type WatchConfig struct {
	LocalRoot  string
	RemoteRoot string
	Silent     bool
	Workers    int
	StateDir   string
	DBPath     string
	LogPath    string
	LockPath   string

	RemotePoll, DeepScan, Debounce time.Duration
}

// WatchLoopFunc runs the actual event/poll/deep-scan loop (watch.Run) once
// RunWatch has finished its setup. It is injected by the caller rather than
// called directly from this package because the watch package already
// imports app (for RobustParams/RunRobustOnce - see
// internal/watch/incremental.go and loop.go); app importing watch back would
// be an import cycle. internal/cli, which imports both app and watch, is
// where the two are wired together for real (see cli/watch_cmd.go); tests of
// RunWatch's setup/lifecycle can inject a fake instead of pulling in a real
// fsnotify watcher.
type WatchLoopFunc func(ctx context.Context, p RobustParams, matcher *fs.IgnoreMatcher, cfg WatchConfig) error

// RunWatch bootstraps and runs the always-on watch daemon: it resolves both
// roots' symlinks once up front and uses the resolved paths for everything
// downstream (see resolveWatchRoot - review finding), rejects overlapping
// roots (same rootsOverlap check SyncOnce uses - a destination nested inside
// its own source, or vice versa, double-keys files across the two scans and
// corrupts reconciliation, notably on the first deep scan; review finding),
// resolves runtime paths, builds the logger, acquires the daemon lock (held
// for the whole process lifetime - only one watcher may run per local root
// at a time), verifies the remote canary once up front (the loop re-checks
// it on every cycle thereafter), opens the manifest db, loads the ignore
// matcher, and then hands off to runLoop (watch.Run in production), which
// blocks until ctx is cancelled.
func RunWatch(ctx context.Context, cfg WatchConfig, runLoop WatchLoopFunc) error {
	resolvedLocal, err := resolveWatchRoot("local", cfg.LocalRoot)
	if err != nil {
		return err
	}
	resolvedRemote, err := resolveWatchRoot("remote", cfg.RemoteRoot)
	if err != nil {
		return err
	}
	cfg.LocalRoot = resolvedLocal
	cfg.RemoteRoot = resolvedRemote

	overlap, err := rootsOverlap(cfg.LocalRoot, cfg.RemoteRoot)
	if err != nil {
		return fmt.Errorf("resolve watch roots: %w", err)
	}
	if overlap {
		return fmt.Errorf("local and remote watch roots must not be the same directory or nested inside one another: %s, %s", cfg.LocalRoot, cfg.RemoteRoot)
	}

	paths, err := runtime.ResolvePaths(runtime.Config{
		LocalRoot:  cfg.LocalRoot,
		RemoteRoot: cfg.RemoteRoot,
		StateDir:   cfg.StateDir,
		DBPath:     cfg.DBPath,
		LogPath:    cfg.LogPath,
		LockPath:   cfg.LockPath,
	})
	if err != nil {
		return err
	}

	logger, err := runtime.NewLogger(cfg.Silent, paths.LogPath)
	if err != nil {
		return err
	}
	defer logger.Close()
	// The default log is named per root pair, so say where it is.
	logger.Printf("syncd watch: local=%s remote=%s log=%s", cfg.LocalRoot, cfg.RemoteRoot, paths.LogPath)

	lock, err := runtime.AcquireLock(paths.LockPath)
	if err != nil {
		return err
	}
	defer lock.Release()

	if err := runtime.CheckRemoteCanary(cfg.RemoteRoot); err != nil {
		return err
	}

	sqlDB, err := db.Open(paths.DBPath)
	if err != nil {
		return err
	}
	defer sqlDB.Close()
	repo := db.NewManifestRepo(sqlDB)

	matcher, err := fs.LoadIgnoreMatcher(cfg.LocalRoot)
	if err != nil {
		return err
	}

	p := RobustParams{
		LocalRoot:  cfg.LocalRoot,
		RemoteRoot: cfg.RemoteRoot,
		Workers:    cfg.Workers,
		Repo:       repo,
		DB:         sqlDB,
		Logger:     logger,
	}

	return runLoop(ctx, p, matcher, cfg)
}

// resolveWatchRoot resolves root's symlinks (filepath.Abs, used to resolve
// --local/--remote before RunWatch is ever called, does not resolve
// symlinks) and confirms the result is a directory. NewWatcher
// (internal/watch/watcher.go) already does this same resolution for its own
// fsnotify tree, since filepath.WalkDir lstats its root argument and never
// follows a symlink there - a walk over an unresolved symlinked root visits
// nothing. That resolution was local to NewWatcher alone: RobustParams (and
// every ScanTree-driven poll/deep-scan cycle built from it) still carried
// the raw root, so a full scan over an unresolved symlinked root also saw
// that side as completely empty - and once a manifest baseline existed,
// BuildPlan read every already-synced file on the OTHER side as deleted and
// removed it (review finding, GPT-5.6 Sol). Resolving once here, before
// RobustParams is ever built, means every downstream consumer (the ignore
// matcher, the scanner, the watcher) agrees on the same canonical path.
func resolveWatchRoot(label, root string) (string, error) {
	resolved, err := filepath.EvalSymlinks(root)
	if err != nil {
		return "", fmt.Errorf("resolve %s watch root %s: %w", label, root, err)
	}
	info, err := os.Stat(resolved)
	if err != nil {
		return "", fmt.Errorf("stat %s watch root %s: %w", label, root, err)
	}
	if !info.IsDir() {
		return "", fmt.Errorf("%s watch root is not a directory: %s", label, root)
	}
	return resolved, nil
}
package watch

import (
	"context"
	"errors"
	"os"
	"path/filepath"
	"sync"
	"time"

	"github.com/fsnotify/fsnotify"

	"syncd/internal/app"
	"syncd/internal/fs"
	"syncd/internal/runtime"
)

// LoopConfig configures the always-on watch loop's three sync triggers.
type LoopConfig struct {
	RemotePoll time.Duration // full remote HashIfChanged cycle cadence (default 30s)
	DeepScan   time.Duration // full-tree HashIfChanged safety net (default 1h)
	Debounce   time.Duration // watcher batch window (default 500ms)
}

// Defaults substituted for a non-positive RemotePoll/DeepScan (see Run):
// these match the --remote-poll/--deep-scan flag defaults documented in
// internal/cli/watch_cmd.go.
const (
	defaultRemotePoll = 30 * time.Second
	defaultDeepScan   = time.Hour
)

// newTicker is time.NewTicker, indirected through a package-level variable
// purely so tests can observe which durations Run actually passes to it -
// e.g. confirming a non-positive RemotePoll/DeepScan really gets clamped to
// the documented 30s/1h defaults - without a full fake clock. Same pattern
// as watcher.go's fsAdd.
var newTicker = time.NewTicker

// newWatcher is NewWatcher, indirected so tests can reach the Watcher Run
// creates (e.g. to inject an fsnotify error). Same pattern as newTicker.
var newWatcher = NewWatcher

// Run blocks until ctx is cancelled. It starts an fsnotify Watcher on
// p.LocalRoot and drives three triggers, each running one reconcile cycle:
//
//   - a batch from the Watcher -> a SCOPED ReconcilePaths over just the
//     changed paths (Task 11) - fast, but never walks the tree, so it can't
//     see new empty directories or the children of a recursively-deleted
//     local directory (fsnotify only surfaces the top-level path for those).
//   - cfg.RemotePoll ticks -> a full RunRobustOnce (whole tree, HashIfChanged)
//   - this is what catches writes made directly on the remote by another
//     machine, since a network mount can't be watched by fsnotify.
//   - cfg.DeepScan ticks -> the same full RunRobustOnce, run as a periodic
//     safety net; it is the ONLY trigger that reconciles new empty
//     directories and recursively-deleted local directories (see above), so
//     it must not be disabled in production.
//
// All three triggers are serialized through a single mutex so cycles never
// overlap - concurrent scans/writes against the same manifest and files
// would corrupt state. Each cycle re-checks the remote canary
// (runtime.CheckRemoteCanary) before touching anything; if the canary check
// fails (e.g. the network mount vanished), the cycle is logged and skipped
// - Run itself never exits because of it, and the next tick/batch retries.
//
// Run returns nil on clean ctx cancellation (after closing the Watcher) or
// a non-nil error if the Watcher itself failed to start.
func Run(ctx context.Context, p app.RobustParams, matcher *fs.IgnoreMatcher, cfg LoopConfig) error {
	w, err := newWatcher(p.LocalRoot, matcher, cfg.Debounce)
	if err != nil {
		return err
	}
	// w is replaced when .syncdignore changes (see reloadIgnore), so close
	// whichever watcher is current at exit.
	defer func() { w.Close() }()

	// NewWatcher degrades to partial coverage rather than failing outright
	// when some directories couldn't be added (e.g. Linux's
	// max_user_watches exhausted partway through the walk) - log that once
	// here so it's observable, even though the Watcher itself has no
	// logger (see CLAUDE.md's known follow-up). The periodic deep scan
	// backstops whatever coverage was lost.
	if addErrs := w.AddErrors(); len(addErrs) > 0 {
		p.Logger.Error("watch: some directories could not be watched; coverage is degraded (deep scan will backstop)", map[string]any{
			"count":       len(addErrs),
			"first_error": addErrs[0].Error(),
		})
	}

	// time.NewTicker panics on a non-positive duration. The CLI validates
	// --remote-poll/--deep-scan before they ever get here, but Run defends
	// on its own too - a library must not be able to be made to panic by a
	// caller passing 0 or a negative duration - falling back to the
	// documented flag defaults.
	remotePoll := cfg.RemotePoll
	if remotePoll <= 0 {
		remotePoll = defaultRemotePoll
	}
	deepScan := cfg.DeepScan
	if deepScan <= 0 {
		deepScan = defaultDeepScan
	}

	pollTicker := newTicker(remotePoll)
	defer pollTicker.Stop()
	deepTicker := newTicker(deepScan)
	defer deepTicker.Stop()

	// batches is a local copy of w.Batches() that gets nil'd out once the
	// channel closes, so the select case blocks forever afterward instead of
	// spinning on a closed channel.
	batches := w.Batches()
	watchErrs := w.Errors()

	var mu sync.Mutex

	// guardedCycle serializes cycles through mu, re-checks the remote canary
	// first, and logs+skips fn on either a vanished canary or a cycle error
	// - it never returns an error to the caller, since a single bad cycle
	// must not stop the always-on loop.
	guardedCycle := func(fn func() error) {
		mu.Lock()
		defer mu.Unlock()
		if err := runtime.CheckRemoteCanary(p.RemoteRoot); err != nil {
			p.Logger.Error("watch: remote canary check failed, skipping cycle", map[string]any{"error": err.Error()})
			return
		}
		if err := fn(); err != nil {
			p.Logger.Error("watch: reconcile cycle failed", map[string]any{"error": err.Error()})
		}
	}

	// Scans reload .syncdignore every cycle, but the watcher's matcher
	// (which decides what is watched at all) was fixed at startup: a
	// directory un-ignored mid-run was never watched, so its changes only
	// arrived via polls (docs/follow-ups.md #28). reloadIgnore rebuilds the
	// watcher with the new rules when the file's content changes - checked
	// when the file itself shows up in a batch, and on every remote poll in
	// case that event was missed (or the file ignores itself). With rescan,
	// it then reconciles the whole tree, since newly un-ignored paths may
	// already hold unsynced files and the old watcher's pending events are
	// gone.
	ignorePath := filepath.Join(p.LocalRoot, fs.IgnoreFileName)
	lastIgnore := ignoreFileSignature(ignorePath)
	reloadIgnore := func(rescan bool) {
		sig := ignoreFileSignature(ignorePath)
		if sig == lastIgnore {
			return
		}
		newMatcher, err := fs.LoadIgnoreMatcher(p.LocalRoot)
		if err != nil {
			// Keep the old rules; scans will fail on the same error until
			// the file is fixed, which is the louder signal.
			p.Logger.Error("watch: .syncdignore changed but could not be loaded; keeping previous rules", map[string]any{"error": err.Error()})
			lastIgnore = sig
			return
		}
		nw, err := newWatcher(p.LocalRoot, newMatcher, cfg.Debounce)
		if err != nil {
			p.Logger.Error("watch: could not rebuild watcher for new .syncdignore; keeping the old one", map[string]any{"error": err.Error()})
			return // lastIgnore unchanged: retried at the next check
		}
		_ = w.Close()
		w = nw
		batches, watchErrs = w.Batches(), w.Errors()
		lastIgnore = sig
		p.Logger.Printf("watch: .syncdignore changed; watcher rebuilt with the new rules")
		if rescan {
			guardedCycle(func() error {
				rescanParams := p
				rescanParams.Policy = fs.HashIfChanged
				_, _, err := app.RunRobustOnce(ctx, rescanParams)
				return err
			})
		}
	}

	for {
		select {
		case <-ctx.Done():
			return nil

		case batch, ok := <-batches:
			if !ok {
				// Watcher shut itself down (fsnotify Events/Errors closed).
				// Keep serving ticks; nothing more will ever arrive on this
				// channel, so nil it out (a nil channel blocks forever in
				// select) rather than spin on the closed channel.
				batches = nil
				continue
			}
			guardedCycle(func() error {
				_, err := ReconcilePaths(ctx, p, batch)
				return err
			})
			if _, ok := batch[fs.IgnoreFileName]; ok {
				reloadIgnore(true)
			}

		case werr, ok := <-watchErrs:
			if !ok {
				watchErrs = nil
				continue
			}
			if !errors.Is(werr, fsnotify.ErrEventOverflow) {
				p.Logger.Error("watch: filesystem watcher error", map[string]any{"error": werr.Error()})
				continue
			}
			// The kernel dropped events: some local changes may never
			// arrive as a batch. Reconcile the whole tree now rather than
			// leaving them until the next remote poll / deep scan.
			p.Logger.Error("watch: filesystem event queue overflowed; running a full rescan", map[string]any{"error": werr.Error()})
			guardedCycle(func() error {
				rescanParams := p
				rescanParams.Policy = fs.HashIfChanged
				_, _, err := app.RunRobustOnce(ctx, rescanParams)
				return err
			})
			drainQueuedErrors(watchErrs, p.Logger)

		case <-pollTicker.C:
			reloadIgnore(false) // this poll is itself the full rescan
			guardedCycle(func() error {
				pollParams := p
				pollParams.Policy = fs.HashIfChanged
				_, _, err := app.RunRobustOnce(ctx, pollParams)
				return err
			})

		case <-deepTicker.C:
			guardedCycle(func() error {
				deepParams := p
				deepParams.Policy = fs.HashAlways
				_, _, err := app.RunRobustOnce(ctx, deepParams)
				return err
			})
		}
	}
}

// drainQueuedErrors empties errs without blocking - called right after an
// overflow-triggered full rescan, which has just covered whatever further
// queued overflows (typically more of the same burst) could have meant, so
// those are dropped instead of each triggering another full rescan. Any
// other error is still logged.
func drainQueuedErrors(errs <-chan error, logger *runtime.Logger) {
	for {
		select {
		case err, ok := <-errs:
			if !ok {
				return
			}
			if !errors.Is(err, fsnotify.ErrEventOverflow) {
				logger.Error("watch: filesystem watcher error", map[string]any{"error": err.Error()})
			}
		default:
			return
		}
	}
}

// ignoreFileSignature identifies the current content of the ignore file
// (its bytes, or a marker for "absent/unreadable") so reloadIgnore can tell
// a real change from an event that left it the same.
func ignoreFileSignature(path string) string {
	b, err := os.ReadFile(path)
	if err != nil {
		return "\x00absent"
	}
	return string(b)
}

