package execute

import (
	"context"
	"errors"
	"fmt"
	"os"
	"path/filepath"
	"sync"
	"time"

	"syncd/internal/db"
	"syncd/internal/fs"
	"syncd/internal/reconcile"
)

type SyncState struct {
	LocalRoot   string
	RemoteRoot  string
	LocalFiles  map[string]fs.FileEntry
	RemoteFiles map[string]fs.FileEntry
}

type ManifestUpdate struct {
	Path   string
	Delete bool
	Row    db.ManifestRow
}

type Result struct {
	Action  reconcile.Action
	Error   error
	Updates []ManifestUpdate
}

func RunActions(ctx context.Context, workers int, state SyncState, actions []reconcile.Action) ([]Result, error) {
	if workers < 1 {
		workers = 1
	}

	jobs := make(chan reconcile.Action)
	results := make(chan Result, len(actions))

	var wg sync.WaitGroup
	for i := 0; i < workers; i++ {
		wg.Add(1)
		go func() {
			defer wg.Done()
			for action := range jobs {
				if err := ctx.Err(); err != nil {
					results <- Result{Action: action, Error: err}
					continue
				}
				results <- applyAction(state, action)
			}
		}()
	}

	// Feeding and draining run as independent goroutines so that an early
	// return here (on cancellation) still always closes jobs, and workers
	// finishing still always closes results - neither side can leave the
	// other blocked forever.
	go func() {
		defer close(jobs)
		for _, action := range actions {
			select {
			case <-ctx.Done():
				return
			case jobs <- action:
			}
		}
	}()

	go func() {
		wg.Wait()
		close(results)
	}()

	out := make([]Result, 0, len(actions))
	cancelled := false
	for res := range results {
		if res.Error != nil && ctx.Err() != nil && errors.Is(res.Error, ctx.Err()) {
			cancelled = true
		}
		out = append(out, res)
	}
	// Report cancellation to the caller even though we still return whatever
	// partial results completed - the caller decides what to do with them
	// (e.g. still commit manifest updates for actions that finished). But
	// only when cancellation actually cut the batch short: a SIGINT landing
	// after the last action already finished must not make a fully
	// successful run report "did not complete" (docs/follow-ups.md #16).
	if cancelled || len(out) < len(actions) {
		return out, ctx.Err()
	}
	return out, nil
}

// ErrDestinationChanged reports that an action's destination no longer
// matches what this cycle's scan saw (it was created, modified, replaced,
// or - for an overwrite - removed in between). The action is skipped rather
// than applied, with no manifest update, so the next cycle re-plans it from
// fresh state. Without this guard, a slow full-tree cycle over SMB leaves a
// wide window in which a user's (or another machine's) write to the
// destination is silently overwritten by a copy, or destroyed by a delete,
// planned against a now-stale scan.
var ErrDestinationChanged = errors.New("destination changed since scan; deferring to next cycle")

// verifyDestinationUnchanged checks absPath against the scan's view of it:
// scanned/present is the entry (if any) the scan recorded for that path on
// the destination side. A path the scan saw absent must still be absent; a
// path the scan saw must still be a regular file with the same size and
// mtime. allowVanished tolerates a scanned path that has since disappeared
// (correct for deletes, whose goal state is "absent" anyway).
func verifyDestinationUnchanged(absPath string, scanned fs.FileEntry, present, allowVanished bool) error {
	info, err := os.Lstat(absPath)
	if err != nil {
		if !os.IsNotExist(err) {
			return fmt.Errorf("stat destination: %w", err)
		}
		if !present || allowVanished {
			return nil
		}
		return fmt.Errorf("%w (scanned present, now missing)", ErrDestinationChanged)
	}
	if !present {
		return fmt.Errorf("%w (scanned absent, now exists)", ErrDestinationChanged)
	}
	if !info.Mode().IsRegular() {
		return fmt.Errorf("%w (no longer a regular file)", ErrDestinationChanged)
	}
	if info.Size() != scanned.Size || info.ModTime().Unix() != scanned.Mtime {
		return fmt.Errorf("%w (size/mtime %d/%d, scanned %d/%d)", ErrDestinationChanged, info.Size(), info.ModTime().Unix(), scanned.Size, scanned.Mtime)
	}
	return nil
}

func applyAction(state SyncState, action reconcile.Action) Result {
	switch action.Type {
	case reconcile.ActionNoOp:
		return Result{Action: action}
	case reconcile.ActionUpload:
		return runUpload(state, action)
	case reconcile.ActionDownload:
		return runDownload(state, action)
	case reconcile.ActionDeleteRemote:
		return runDelete(state, action, false)
	case reconcile.ActionDeleteLocal:
		return runDelete(state, action, true)
	case reconcile.ActionConflict:
		return runConflict(state, action)
	default:
		return Result{
			Action: action,
			Error:  fmt.Errorf("unknown action type %s", action.Type),
		}
	}
}

func runUpload(state SyncState, action reconcile.Action) Result {
	local, ok := state.LocalFiles[action.Path]
	if !ok {
		return Result{Action: action, Error: fmt.Errorf("upload source missing: %s", action.Path)}
	}
	dst := filepath.Join(state.RemoteRoot, filepath.FromSlash(action.Path))
	scanned, present := state.RemoteFiles[action.Path]
	if err := verifyDestinationUnchanged(dst, scanned, present, false); err != nil {
		return Result{Action: action, Error: fmt.Errorf("upload %s: %w", action.Path, err)}
	}
	if err := fs.AtomicCopyFile(local.AbsPath, dst); err != nil {
		return Result{Action: action, Error: fmt.Errorf("upload %s: %w", action.Path, err)}
	}
	return Result{
		Action: action,
		Updates: []ManifestUpdate{
			{Path: action.Path, Row: db.ManifestRow{
				Path: action.Path, Size: local.Size, Mtime: local.Mtime, Hash: local.Hash, LastSynced: time.Now().Unix(),
			}},
		},
	}
}

func runDownload(state SyncState, action reconcile.Action) Result {
	remote, ok := state.RemoteFiles[action.Path]
	if !ok {
		return Result{Action: action, Error: fmt.Errorf("download source missing: %s", action.Path)}
	}
	dst := filepath.Join(state.LocalRoot, filepath.FromSlash(action.Path))
	scanned, present := state.LocalFiles[action.Path]
	if err := verifyDestinationUnchanged(dst, scanned, present, false); err != nil {
		return Result{Action: action, Error: fmt.Errorf("download %s: %w", action.Path, err)}
	}
	if err := fs.AtomicCopyFile(remote.AbsPath, dst); err != nil {
		return Result{Action: action, Error: fmt.Errorf("download %s: %w", action.Path, err)}
	}
	return Result{
		Action: action,
		Updates: []ManifestUpdate{
			{Path: action.Path, Row: db.ManifestRow{
				Path: action.Path, Size: remote.Size, Mtime: remote.Mtime, Hash: remote.Hash, LastSynced: time.Now().Unix(),
			}},
		},
	}
}

func runDelete(state SyncState, action reconcile.Action, deleteLocal bool) Result {
	targetRoot, targetFiles := state.RemoteRoot, state.RemoteFiles
	if deleteLocal {
		targetRoot, targetFiles = state.LocalRoot, state.LocalFiles
	}
	targetPath := filepath.Join(targetRoot, filepath.FromSlash(action.Path))
	// BuildPlan only deletes a path it saw, unchanged since the manifest, on
	// the target side - so the target must still be exactly that file. If it
	// was edited in the meantime, deleting it would destroy the edit.
	scanned, present := targetFiles[action.Path]
	if err := verifyDestinationUnchanged(targetPath, scanned, present, true); err != nil {
		return Result{Action: action, Error: fmt.Errorf("delete %s: %w", action.Path, err)}
	}
	if err := removeIfExists(targetPath); err != nil {
		return Result{Action: action, Error: fmt.Errorf("delete %s: %w", action.Path, err)}
	}
	return Result{
		Action: action,
		Updates: []ManifestUpdate{
			{Path: action.Path, Delete: true},
		},
	}
}

func removeIfExists(path string) error {
	if err := os.Remove(path); err != nil && !os.IsNotExist(err) {
		return err
	}
	return nil
}
package execute

import (
	"context"
	"fmt"
	"os"
	"path/filepath"
	"sync"

	"syncd/internal/fs"
	"syncd/internal/reconcile"
)

// ProgressSink receives progress updates from RunFastTasks. It is satisfied
// by a pterm-backed sink in the cli layer and by a nop in tests. progress
// may be nil, in which case no progress is reported.
type ProgressSink interface {
	// Start is called once before any task runs, with the total number of
	// tasks about to be processed. This gives the progress bar a real
	// denominator instead of a placeholder.
	Start(totalTasks int)
	// Advance reports that one task completed, transferring bytes bytes
	// (0 for deletes and moves). It is called once per task, so the bar
	// ticks per file rather than by raw byte count.
	Advance(bytes int64)
	Done()
}

// RunFastTasks executes fast tasks against the two roots using atomic writes.
// progress may be nil (non-interactive). Returns the first error encountered.
func RunFastTasks(ctx context.Context, workers int, left, right string, tasks []reconcile.FastTask, progress ProgressSink) error {
	if workers < 1 {
		workers = 1
	}

	jobs := make(chan reconcile.FastTask)
	errs := make(chan error, len(tasks))

	if progress != nil {
		progress.Start(len(tasks))
	}

	var wg sync.WaitGroup
	for i := 0; i < workers; i++ {
		wg.Add(1)
		go func() {
			defer wg.Done()
			for task := range jobs {
				if err := ctx.Err(); err != nil {
					errs <- err
					continue
				}
				err := applyFastTask(left, right, task)
				if err == nil && progress != nil {
					progress.Advance(task.Size)
				}
				errs <- err
			}
		}()
	}

	// Feeding and draining run as independent goroutines so that an early
	// return here (on cancellation) still always closes jobs, and workers
	// finishing still always closes errs - neither side can leave the other
	// blocked forever.
	go func() {
		defer close(jobs)
		for _, task := range tasks {
			select {
			case <-ctx.Done():
				return
			case jobs <- task:
			}
		}
	}()

	go func() {
		wg.Wait()
		close(errs)
	}()

	var firstErr error
	for err := range errs {
		if err != nil && firstErr == nil {
			firstErr = err
		}
	}

	if progress != nil {
		progress.Done()
	}

	if firstErr != nil {
		return firstErr
	}
	return ctx.Err()
}

func applyFastTask(left, right string, task reconcile.FastTask) error {
	switch task.Type {
	case reconcile.CopyL2R:
		src := filepath.Join(left, filepath.FromSlash(task.RelPath))
		dst := filepath.Join(right, filepath.FromSlash(task.RelPath))
		return fs.AtomicCopyFile(src, dst)
	case reconcile.CopyR2L:
		src := filepath.Join(right, filepath.FromSlash(task.RelPath))
		dst := filepath.Join(left, filepath.FromSlash(task.RelPath))
		return fs.AtomicCopyFile(src, dst)
	case reconcile.ConflictL2R:
		return copyPreservingDestination(left, right, task.RelPath)
	case reconcile.ConflictR2L:
		return copyPreservingDestination(right, left, task.RelPath)
	case reconcile.DeleteL:
		return removeIfExists(filepath.Join(left, filepath.FromSlash(task.RelPath)))
	case reconcile.DeleteR:
		return removeIfExists(filepath.Join(right, filepath.FromSlash(task.RelPath)))
	case reconcile.MoveL:
		return moveFastFile(left, task)
	case reconcile.MoveR:
		return moveFastFile(right, task)
	default:
		return fmt.Errorf("unknown action type %s", task.Type)
	}
}

// moveFastFile moves a file within root from task.OldRelPath to
// task.RelPath. It tries os.Rename first, falling back to an atomic
// copy+remove when rename fails (e.g. across devices).
func moveFastFile(root string, task reconcile.FastTask) error {
	src := filepath.Join(root, filepath.FromSlash(task.OldRelPath))
	dst := filepath.Join(root, filepath.FromSlash(task.RelPath))

	if err := os.MkdirAll(filepath.Dir(dst), 0o755); err != nil {
		return err
	}

	if err := renameFunc(src, dst); err != nil {
		if err := copyFunc(src, dst); err != nil {
			return err
		}
		// os.Remove, not os.RemoveAll: FastCompare only queues a move for
		// paths it saw as FILES during scanning. If src was replaced by a
		// non-empty directory between scan and now (a TOCTOU race), os.Remove
		// fails safely with ENOTEMPTY rather than silently wiping the whole
		// subtree - the same safety convention used by DeleteL/DeleteR tasks
		// (see TestApplyFastTask_DeleteFailsSafelyWhenPathIsActuallyANonEmptyDirectory).
		return os.Remove(src)
	}
	return nil
}

// renameFunc is os.Rename, indirected through a package-level variable so
// tests can force the copy+remove fallback path in moveFastFile
// deterministically (simulating a cross-device rename failure) without
// needing an actual cross-device filesystem setup. Same pattern as
// conflict.go's timeNow and atomic_copy.go's tempSiblingPathFunc.
var renameFunc = os.Rename

// copyFunc is fs.AtomicCopyFile, indirected through a package-level variable
// so tests can simulate the copy succeeding and then src being replaced by a
// non-empty directory before the subsequent os.Remove(src) call - the TOCTOU
// race that call guards against - without needing real concurrent
// filesystem mutation.
var copyFunc = fs.AtomicCopyFile

// copyPreservingDestination copies srcRoot/rel over dstRoot/rel, first
// renaming any existing destination aside to a conflict copy (the same
// "_conflict_<ts>" naming the robust engine uses) so the losing side of a
// two-way conflict is kept rather than overwritten. If the copy fails, the
// destination is put back.
func copyPreservingDestination(srcRoot, dstRoot, rel string) error {
	src := filepath.Join(srcRoot, filepath.FromSlash(rel))
	dst := filepath.Join(dstRoot, filepath.FromSlash(rel))
	if _, err := os.Lstat(dst); err != nil {
		if os.IsNotExist(err) {
			return copyFunc(src, dst) // nothing to preserve
		}
		return fmt.Errorf("stat conflict destination %s: %w", rel, err)
	}
	conflictRel, err := findAvailableConflictPath(srcRoot, dstRoot, rel, timeNow().UTC())
	if err != nil {
		return err
	}
	preserved := filepath.Join(dstRoot, filepath.FromSlash(conflictRel))
	if err := renameFunc(dst, preserved); err != nil {
		return fmt.Errorf("preserve conflicting %s: %w", rel, err)
	}
	if err := copyFunc(src, dst); err != nil {
		if rerr := renameFunc(preserved, dst); rerr != nil {
			return fmt.Errorf("copy %s after preserving conflict copy: %w (restore also failed, original kept at %s: %v)", rel, err, conflictRel, rerr)
		}
		return fmt.Errorf("copy %s after preserving conflict copy: %w", rel, err)
	}
	return nil
}
package reconcile

import (
	"sort"

	"syncd/internal/db"
	"syncd/internal/fs"
)

type ActionType string

const (
	ActionNoOp         ActionType = "NO_OP"
	ActionUpload       ActionType = "UPLOAD"
	ActionDownload     ActionType = "DOWNLOAD"
	ActionDeleteRemote ActionType = "DELETE_REMOTE"
	ActionDeleteLocal  ActionType = "DELETE_LOCAL"
	ActionConflict     ActionType = "CONFLICT"
)

type Action struct {
	Type   ActionType `json:"type"`
	Path   string     `json:"path"`
	Reason string     `json:"reason"`
}

type Plan struct {
	Actions []Action `json:"actions"`
}

func BuildPlan(
	local map[string]fs.FileEntry,
	remote map[string]fs.FileEntry,
	manifest map[string]db.ManifestRow,
	skipped SkipSet,
) Plan {
	keys := allKeys(local, remote, manifest)
	actions := make([]Action, 0, len(keys))

	for _, path := range keys {
		if skipped.Contains(path) {
			continue
		}
		manifestRow, inManifest := manifest[path]
		l, inLocal := local[path]
		r, inRemote := remote[path]

		if inLocal && inRemote {
			if l.Hash == r.Hash {
				actions = append(actions, Action{Type: ActionNoOp, Path: path, Reason: "hashes match"})
				continue
			}
			if !inManifest {
				actions = append(actions, Action{Type: ActionConflict, Path: path, Reason: "first-sync path collision with differing content"})
				continue
			}
			localChanged := l.Hash != manifestRow.Hash
			remoteChanged := r.Hash != manifestRow.Hash
			switch {
			case localChanged && remoteChanged:
				actions = append(actions, Action{Type: ActionConflict, Path: path, Reason: "modified on both sides since last sync"})
			case localChanged:
				actions = append(actions, Action{Type: ActionUpload, Path: path, Reason: "local changed; remote unchanged"})
			case remoteChanged:
				actions = append(actions, Action{Type: ActionDownload, Path: path, Reason: "remote changed; local unchanged"})
			default:
				actions = append(actions, Action{Type: ActionConflict, Path: path, Reason: "diverged from manifest without side attribution"})
			}
			continue
		}

		if inLocal && !inRemote {
			if !inManifest {
				actions = append(actions, Action{Type: ActionUpload, Path: path, Reason: "new local file"})
				continue
			}
			localChanged := l.Hash != manifestRow.Hash
			if localChanged {
				actions = append(actions, Action{Type: ActionUpload, Path: path, Reason: "local changed while remote deleted; preserving changed file"})
			} else {
				actions = append(actions, Action{Type: ActionDeleteLocal, Path: path, Reason: "remote deleted; propagating delete"})
			}
			continue
		}

		if !inLocal && inRemote {
			if !inManifest {
				actions = append(actions, Action{Type: ActionDownload, Path: path, Reason: "new remote file"})
				continue
			}
			remoteChanged := r.Hash != manifestRow.Hash
			if remoteChanged {
				actions = append(actions, Action{Type: ActionDownload, Path: path, Reason: "remote changed while local deleted; preserving changed file"})
			} else {
				actions = append(actions, Action{Type: ActionDeleteRemote, Path: path, Reason: "local deleted; propagating delete"})
			}
			continue
		}

		if inManifest {
			actions = append(actions, Action{Type: ActionNoOp, Path: path, Reason: "already deleted on both sides"})
		}
	}

	sort.SliceStable(actions, func(i, j int) bool {
		if actions[i].Type == actions[j].Type {
			return actions[i].Path < actions[j].Path
		}
		return actions[i].Type < actions[j].Type
	})

	return Plan{Actions: actions}
}

func allKeys(
	local map[string]fs.FileEntry,
	remote map[string]fs.FileEntry,
	manifest map[string]db.ManifestRow,
) []string {
	set := make(map[string]struct{}, len(local)+len(remote)+len(manifest))
	for k := range local {
		set[k] = struct{}{}
	}
	for k := range remote {
		set[k] = struct{}{}
	}
	for k := range manifest {
		set[k] = struct{}{}
	}
	keys := make([]string, 0, len(set))
	for k := range set {
		keys = append(keys, k)
	}
	sort.Strings(keys)
	return keys
}
