20	// RobustParams configures a single robust, hash-based three-way sync cycle
21	// run by RunRobustOnce. It is the shared engine behind the `syncd watch`
22	// daemon (internal/watch) and the `syncd sync --hash` bridge (see
23	// sync_once.go).
24	type RobustParams struct {
25		LocalRoot, RemoteRoot string
26		Workers               int
27		Repo                  *db.ManifestRepo
28		DB                    *sql.DB
29		Logger                *runtime.Logger
30		Policy                fs.HashPolicy // HashIfChanged for polls, HashAlways for deep verify
31		// ConfirmPlan, if set, is shown the non-NoOp actions RunRobustOnce is
32		// about to execute, plus the directory creates/removes it will make
33		// (dirOps lists only those that change a tree), and may decline them
34		// (return false), in which case
35		// RunRobustOnce returns ErrAborted having changed nothing - no file
36		// action, no directory create/remove, no manifest write. It is how
37		// `syncd sync --hash`'s interactive confirm approves exactly the plan
38		// that then runs, rather than a separate preview scan's plan. nil
39		// (watch, --yes) means "always proceed".
40		ConfirmPlan func(actions []reconcile.Action, dirOps []DirOp) bool
41	}
42	
43	// robustHardError marks an error from RunRobustOnce that happened before -
44	// or in the course of committing - a run's results: Repo.LoadAll,
45	// fs.ScanPair, or Repo.ApplyUpdates. It is distinct from the
46	// execute.RunActions runErr (e.g. context cancellation), which RunRobustOnce
47	// returns bare after the manifest commit has already been attempted.
48	//
49	// Callers use this distinction to reproduce the pre-RunRobustOnce
50	// error-reporting shape of their own call site: a hard failure is reported
51	// immediately (no run-summary logging), using that call site's own
52	// (possibly stage-specific) wrapping of the plain underlying error; a runErr
53	// or failures>0 result is reported only after a run summary is emitted,
54	// wrapped as "sync run did not complete" / "sync completed with N failed
55	// action(s)" respectively. See sync_once.go's runRobustOnce for the call
56	// site that branches on this.
57	type robustHardError struct {
58		stage string // "load manifest", "scan", or "apply manifest updates"
59		err   error
60	}
61	
62	func (e *robustHardError) Error() string { return e.err.Error() }
63	func (e *robustHardError) Unwrap() error { return e.err }
64	
65	// RunRobustOnce performs one scan -> plan -> execute -> manifest-update
66	// (plus empty-dir create/cleanup) cycle of the robust, hash-based three-way
67	// engine and returns the executed plan and the number of failed actions.
68	//
69	// The returned error is either nil, a *robustHardError (LoadAll/ScanPair/
70	// ApplyUpdates failed - see its doc comment), or the bare execute.RunActions
71	// runErr (e.g. context cancellation) after a manifest commit was attempted.
72	func RunRobustOnce(ctx context.Context, p RobustParams) (reconcile.Plan, int, error) {
73		manifest, err := p.Repo.LoadAll(ctx)
74		if err != nil {
75			return reconcile.Plan{}, 0, &robustHardError{stage: "load manifest", err: err}
76		}
77	
78		dirRepo := db.NewDirRepo(p.DB)
79		dirBaseline, err := dirRepo.LoadAll(ctx)
80		if err != nil {
81			return reconcile.Plan{}, 0, &robustHardError{stage: "load dir manifest", err: err}
82		}
83	
84		scans, err := fs.ScanPair(ctx, p.LocalRoot, p.RemoteRoot, manifest, p.Policy, scanProgressLogger(p.Logger))
85		if err != nil {
86			return reconcile.Plan{}, 0, &robustHardError{stage: "scan", err: err}
87		}
88		logScanIssues(p.Logger, "local", scans.Local.Issues)
89		logScanIssues(p.Logger, "remote", scans.Remote.Issues)
90	
91		localFiles, remoteFiles := scans.Local.Files, scans.Remote.Files
92		skipped := mergeSkipSet(scans.Local, scans.Remote)
93		plan := reconcile.BuildPlan(localFiles, remoteFiles, manifest, skipped)
94	
95		execActions := make([]reconcile.Action, 0, len(plan.Actions))
96		for _, action := range plan.Actions {
97			if action.Type != reconcile.ActionNoOp {
98				execActions = append(execActions, action)
99			}
100		}
101	
102		// Planned from the scan now, applied after the file actions below (the
103		// same scan-time view the apply step always used), so the confirm can
104		// show directory operations too.
105		dirOps := planDirectories(scans.Local.Dirs, scans.Remote.Dirs, dirBaseline, skipped)
106		if p.ConfirmPlan != nil && !p.ConfirmPlan(execActions, visibleDirOps(dirOps)) {
107			return plan, 0, ErrAborted
108		}
109	
110		state := execute.SyncState{
111			LocalRoot:   p.LocalRoot,
112			RemoteRoot:  p.RemoteRoot,
113			LocalFiles:  localFiles,
114			RemoteFiles: remoteFiles,
115		}
116		// runErr (e.g. context cancellation) is deliberately not returned yet:
117		// results may be partial, but whatever did complete should still be
118		// committed to the manifest below before we report failure.
119		results, runErr := execute.RunActions(ctx, p.Workers, state, execActions)
120	
121		upserts, deletes, failures := collectManifestUpdates(results, p.Logger)
122	
123		dirsToAdd, dirsToRemove, dirFailures := applyDirOps(p.Logger, p.LocalRoot, p.RemoteRoot, dirOps)
124		failures += dirFailures
125		cleanupEmptiedDirs(p.LocalRoot, p.RemoteRoot, deletes)
126	
127		noopUpserts, noopDeletes := noopManifestUpdates(plan, localFiles, remoteFiles, manifest)
128		upserts = append(upserts, noopUpserts...)
129		deletes = append(deletes, noopDeletes...)
130	
131		if err := commitManifestUpdates(ctx, p.Repo, upserts, deletes); err != nil {
132			return plan, failures, &robustHardError{stage: "apply manifest updates", err: err}
133		}
134		// Detached context for the same reason as commitManifestUpdates: a run
135		// cancelled mid-execute.RunActions must not lose directory baseline
136		// updates that already-completed create/removes imply.
137		if err := dirRepo.ApplyUpdates(context.WithoutCancel(ctx), dirsToAdd, dirsToRemove); err != nil {
138			return plan, failures, &robustHardError{stage: "apply dir manifest updates", err: err}
139		}
140	
141		return plan, failures, runErr
142	}
143	
144	// commitManifestUpdates persists this cycle's manifest upserts/deletes,
145	// using a context detached from cancellation (context.WithoutCancel), not
146	// ctx itself. execute.RunActions' runErr (e.g. ctx cancelled mid-batch by
147	// SIGINT) is deliberately not checked before this is called - whatever
148	// actions DID complete should still be recorded - but ctx may already be
149	// Done by the time we get here, and ApplyUpdates' BeginTx fails immediately
150	// against a cancelled context, which would silently drop real,
151	// already-applied filesystem changes from the manifest (review finding
152	// "Medium 7"). It is a no-op (no transaction opened) when there is nothing
153	// to commit.
154	func commitManifestUpdates(ctx context.Context, repo *db.ManifestRepo, upserts []db.ManifestRow, deletes []string) error {
155		if len(upserts) == 0 && len(deletes) == 0 {
156			return nil
157		}
158		return repo.ApplyUpdates(context.WithoutCancel(ctx), upserts, deletes)
159	}
160	
161	// noopManifestUpdates derives the manifest upserts/deletes that
162	// ActionNoOp plan entries require on their own, since they are excluded from
163	// execActions and never reach execute.RunActions (there is nothing to copy -
164	// the point of NoOp is that both sides already agree), and so would
165	// otherwise never touch the manifest at all:
166	//
167	//   - a live matching pair (present, hash-equal, on both sides) that isn't
168	//     already correctly baselined gets a manifest upsert. Without this, a
169	//     pair that has been identical since its very first scan - never having
170	//     gone through an Upload/Download/Conflict action - stays untracked
171	//     forever, so a later one-sided delete falls into BuildPlan's
172	//     `!inManifest` branch and gets re-uploaded ("resurrected") instead of
173	//     propagated as a delete (review finding "High 4").
174	//   - a stale manifest row for a path now absent from both sides (BuildPlan's
175	//     "already deleted on both sides" NoOp) is removed, so it doesn't linger
176	//     in the manifest indefinitely.
177	func noopManifestUpdates(plan reconcile.Plan, localFiles, remoteFiles map[string]fs.FileEntry, manifest map[string]db.ManifestRow) (upserts []db.ManifestRow, deletes []string) {
178		now := time.Now().Unix()
179		for _, action := range plan.Actions {
180			if action.Type != reconcile.ActionNoOp {
181				continue
182			}
183			path := action.Path
184			l, inLocal := localFiles[path]
185			r, inRemote := remoteFiles[path]
186			if inLocal && inRemote {
187				row, ok := manifest[path]
188				remoteSize, remoteMtime := row.RemoteStat()
189				if !ok || row.Hash != l.Hash || row.Size != l.Size || row.Mtime != l.Mtime || remoteSize != r.Size || remoteMtime != r.Mtime {
190					// Record each side's own stat: an identical pair can still
191					// differ in mtime (copied without preserving it), and the
192					// remote HashIfChanged cache needs the REMOTE stat to hit.
193					upserts = append(upserts, db.ManifestRow{
194						Path: path, Size: l.Size, Mtime: l.Mtime, Hash: l.Hash, LastSynced: now,
195						RemoteSize: r.Size, RemoteMtime: r.Mtime,
196					})
197				}
198				continue
199			}
200			if !inLocal && !inRemote {
201				if _, ok := manifest[path]; ok {
202					deletes = append(deletes, path)
203				}
204			}
205		}
206		return upserts, deletes
207	}
208	
209	// collectManifestUpdates dedups a batch of execute.Result into the final set
210	// of manifest upserts and deletes to commit, and counts failed actions. When
211	// the same path appears more than once across results (e.g. a delete
212	// followed by a recreate within one run), the later update wins and any
213	// earlier one for that path is discarded - hence the seen-maps rather than
214	// appending directly. Extracted from RunRobustOnce so RunRobustScoped can
215	// reuse the exact same dedup logic; behavior is unchanged from its inline
216	// original.
217	func collectManifestUpdates(results []execute.Result, logger *runtime.Logger) (upserts []db.ManifestRow, deletes []string, failures int) {
218		seenUpserts := make(map[string]db.ManifestRow)
219		seenDeletes := make(map[string]struct{})
220		for _, res := range results {
221			if res.Error != nil {
222				failures++
223				logger.Error("action failed", map[string]any{
224					"action": res.Action.Type,
225					"path":   res.Action.Path,
226					"error":  res.Error.Error(),
227				})
228				continue
229			}
230			for _, update := range res.Updates {
231				if update.Delete {
232					seenDeletes[update.Path] = struct{}{}
233					delete(seenUpserts, update.Path)
234					continue
235				}
236				seenUpserts[update.Path] = update.Row
237				delete(seenDeletes, update.Path)
238			}
239		}
240	
241		for _, row := range seenUpserts {
242			upserts = append(upserts, row)
243		}
244		for path := range seenDeletes {
245			deletes = append(deletes, path)
246		}
247		sort.Slice(upserts, func(i, j int) bool { return upserts[i].Path < upserts[j].Path })
248		sort.Strings(deletes)
249		return upserts, deletes, failures
250	}
251	
252	// RunRobustScoped reconciles ONLY relPaths (an fsnotify batch) rather than
253	// the whole tree. A file path is stat/hashed on both sides via fs.ScanPaths
254	// - no tree walk. A path that is a DIRECTORY on either side (fsnotify
255	// reports only the top-level path of a recursive delete, a directory
256	// renamed in or out, or a directory created with contents) is expanded:
257	// that subtree alone is walked on whichever side(s) it exists
258	// (fs.ScanSubtree), its manifest rows are loaded by prefix, and its
259	// directories are reconciled against the directory baseline - so a
260	// recursive delete or a directory rename propagates in this cycle instead
261	// of waiting for the next remote poll. The same prefix load is done for a
262	// path that is now absent locally, since it may have been a directory.
263	//
264	// It otherwise mirrors RunRobustOnce's scan -> plan -> execute ->
265	// manifest-commit flow. Directories outside the batch's subtrees (e.g. new
266	// empty directories elsewhere) are left to the periodic full cycles.
267	func RunRobustScoped(ctx context.Context, p RobustParams, relPaths map[string]struct{}) (reconcile.Plan, int, error) {
268		matcher, err := fs.LoadIgnoreMatcher(p.LocalRoot)
269		if err != nil {
270			return reconcile.Plan{}, 0, err
271		}
272		subtrees, prefixes, unknown := scopedSubtrees(p.LocalRoot, p.RemoteRoot, relPaths, matcher)
273	
274		// Only this batch's rows (plus everything beneath its directory
275		// paths): loading the whole manifest per fsnotify batch made the
276		// scoped (hot) path's cost scale with the tree, not the batch.
277		scopedManifest, err := p.Repo.LoadPaths(ctx, relPaths)
278		if err != nil {
279			return reconcile.Plan{}, 0, err
280		}
281		for _, prefix := range prefixes {
282			rows, err := p.Repo.LoadPrefix(ctx, prefix)
283			if err != nil {
284				return reconcile.Plan{}, 0, err
285			}
286			for k, v := range rows {
287				scopedManifest[k] = v
288			}
289		}
290		remoteManifest := db.RemoteStatView(scopedManifest)
291	
292		localScan, err := fs.ScanPaths(p.LocalRoot, relPaths, scopedManifest, p.Policy, true, matcher)
293		if err != nil {
294			return reconcile.Plan{}, 0, err
295		}
296		remoteScan, err := fs.ScanPaths(p.RemoteRoot, relPaths, remoteManifest, p.Policy, false, matcher)
297		if err != nil {
298			return reconcile.Plan{}, 0, err
299		}
300		for _, st := range subtrees {
301			if st.local {
302				sub, err := fs.ScanSubtree(ctx, p.LocalRoot, st.rel, scopedManifest, true, matcher, p.Policy)
303				if err != nil {
304					return reconcile.Plan{}, 0, &robustHardError{stage: "scan", err: err}
305				}
306				mergeScanResult(&localScan, sub)
307			}
308			if st.remote {
309				sub, err := fs.ScanSubtree(ctx, p.RemoteRoot, st.rel, remoteManifest, false, matcher, p.Policy)
310				if err != nil {
311					return reconcile.Plan{}, 0, &robustHardError{stage: "scan", err: err}
312				}
313				mergeScanResult(&remoteScan, sub)
314			}
315		}
316		// A batch path that couldn't be stat'd on one side (e.g. an ancestor
317		// lost search permission) is unknown on that side - and so is
318		// everything beneath it. Mark it as a skipped DIRECTORY, not just an
319		// exact skip (all ScanPaths records for it), so SkipSet suppresses
320		// every descendant too: otherwise the other side's expanded subtree
321		// plus the manifest prefix would read the unreadable side's tracked
322		// children as deleted, and delete the intact copies on the readable
323		// side.
324		for _, u := range unknown {
325			localScan.Skipped[u.rel] = struct{}{}
326			localScan.SkippedDirs[u.rel] = struct{}{}
327			issue := fs.ScanIssue{Path: u.rel, Reason: fmt.Sprintf("lstat: %s; treating its whole subtree as unknown this cycle", u.err)}
328			if u.side == "remote" {
329				remoteScan.Issues = append(remoteScan.Issues, issue)
330			} else {
331				localScan.Issues = append(localScan.Issues, issue)
332			}
333		}
334		logScanIssues(p.Logger, "local", localScan.Issues)
335		logScanIssues(p.Logger, "remote", remoteScan.Issues)
336		skipped := mergeSkipSet(localScan, remoteScan)
337		plan := reconcile.BuildPlan(localScan.Files, remoteScan.Files, scopedManifest, skipped)
338		execActions := nonNoOpActions(plan)
339	
340		// Loaded BEFORE executing anything: once file actions have run, nothing
341		// that can fail on a cancelled ctx may stand between them and
342		// commitManifestUpdates, or completed changes would go unrecorded in
343		// the three-way baseline.
344		dirRepo := db.NewDirRepo(p.DB)
345		var dirBaseline map[string]struct{}
346		if len(subtrees) > 0 {
347			if dirBaseline, err = dirRepo.LoadAll(ctx); err != nil {
348				return plan, 0, &robustHardError{stage: "load dir manifest", err: err}
349			}
350		}
351	
352		state := execute.SyncState{LocalRoot: p.LocalRoot, RemoteRoot: p.RemoteRoot, LocalFiles: localScan.Files, RemoteFiles: remoteScan.Files}
353		results, runErr := execute.RunActions(ctx, p.Workers, state, execActions)
354		scopedActionsDone()
355		upserts, deletes, failures := collectManifestUpdates(results, p.Logger)
356	
357		var dirsToAdd, dirsToRemove []string
358		if len(subtrees) > 0 {
359			var dirFailures int
360			dirsToAdd, dirsToRemove, dirFailures = reconcileDirectories(p.Logger, p.LocalRoot, p.RemoteRoot,
361				localScan.Dirs, remoteScan.Dirs, baselineWithin(dirBaseline, subtrees), skipped)
362			failures += dirFailures
363		}
364		cleanupEmptiedDirs(p.LocalRoot, p.RemoteRoot, deletes)
365	
366		noopUpserts, noopDeletes := noopManifestUpdates(plan, localScan.Files, remoteScan.Files, scopedManifest)
367		upserts = append(upserts, noopUpserts...)
368		deletes = append(deletes, noopDeletes...)
369	
370		if err := commitManifestUpdates(ctx, p.Repo, upserts, deletes); err != nil {
371			return plan, failures, err
372		}
373		// Detached context, as in RunRobustOnce: completed directory
374		// creates/removes must be recorded even if ctx was cancelled.
375		if err := dirRepo.ApplyUpdates(context.WithoutCancel(ctx), dirsToAdd, dirsToRemove); err != nil {
376			return plan, failures, &robustHardError{stage: "apply dir manifest updates", err: err}
377		}
378		return plan, failures, runErr
379	}
380	
381	// scopedSubtree is a batch path that is a directory on at least one side.
382	type scopedSubtree struct {
383		rel           string
384		local, remote bool // which side(s) it is a real directory on
385	}
386	
387	// scopedUnknown is a batch path whose Lstat failed on side ("local" or
388	// "remote") for a reason other than not-existing.
389	type scopedUnknown struct {
390		rel, side string
391		err       error
392	}
393	
394	// scopedLstat is os.Lstat, indirected so tests can simulate a permission
395	// error on one side deterministically (chmod can't, when tests run as
396	// root). Same pattern as watch's newTicker/newWatcher.
397	var scopedLstat = os.Lstat
398	
399	// scopedActionsDone runs right after RunRobustScoped's file actions finish;
400	// a no-op in production. Tests use it to cancel ctx at exactly that point.
401	var scopedActionsDone = func() {}
402	
403	// scopedSubtrees classifies a batch for RunRobustScoped: the directory
404	// paths to walk (outermost only - a path beneath another one in the batch
405	// is already covered by its walk), and the prefixes whose manifest rows
406	// must be loaded: every walked directory, plus every path now absent
407	// locally (it may have been a directory whose tracked contents need
408	// reconciling). Ignored paths are dropped.
409	//
410	// A path whose Lstat fails on either side for any reason other than
411	// not-existing is returned in unknown instead, and neither expanded nor
412	// prefix-loaded: its state on that side is not known, so nothing beneath
413	// it may be planned from this cycle (see RunRobustScoped).
414	func scopedSubtrees(localRoot, remoteRoot string, relPaths map[string]struct{}, matcher *fs.IgnoreMatcher) ([]scopedSubtree, []string, []scopedUnknown) {
415		stat := func(root, rel string) (dir, missing bool, err error) {
416			info, err := scopedLstat(filepath.Join(root, filepath.FromSlash(rel)))
417			if err != nil {
418				if os.IsNotExist(err) {
419					return false, true, nil
420				}
421				return false, false, err
422			}
423			return info.IsDir(), false, nil // Lstat: a symlink is never a directory here
424		}
425		var subtrees []scopedSubtree
426		var prefixes []string
427		var unknown []scopedUnknown
428		for rel := range relPaths {
429			if matcher.MatchPathOrAncestor(rel, true) && matcher.MatchPathOrAncestor(rel, false) {
430				continue // ignored whether file or directory: nothing to do
431			}
432			localDir, localMissing, localErr := stat(localRoot, rel)
433			remoteDir, _, remoteErr := stat(remoteRoot, rel)
434			if localErr != nil || remoteErr != nil {
435				if localErr != nil {
436					unknown = append(unknown, scopedUnknown{rel: rel, side: "local", err: localErr})
437				}
438				if remoteErr != nil {
439					unknown = append(unknown, scopedUnknown{rel: rel, side: "remote", err: remoteErr})
440				}
441				continue
442			}
443			if (localDir || remoteDir) && !matcher.MatchPathOrAncestor(rel, true) {
444				subtrees = append(subtrees, scopedSubtree{rel: rel, local: localDir, remote: remoteDir})
445			} else if localMissing && !matcher.MatchPathOrAncestor(rel, true) {
446				prefixes = append(prefixes, rel)
447			}
448		}
449		// Keep only outermost subtrees.
450		sort.Slice(subtrees, func(i, j int) bool { return subtrees[i].rel < subtrees[j].rel })
451		outer := subtrees[:0]
452		for _, st := range subtrees {
453			if len(outer) > 0 && isWithin(st.rel, outer[len(outer)-1].rel) {
454				continue
455			}
456			outer = append(outer, st)
457		}
458		for _, st := range outer {
459			prefixes = append(prefixes, st.rel)
460		}
461		sort.Strings(prefixes)
462		sort.Slice(unknown, func(i, j int) bool { return unknown[i].rel < unknown[j].rel })
463		return outer, prefixes, unknown
464	}
465	
466	// isWithin reports whether rel is dir itself or beneath it, by whole
467	// path segments.
468	func isWithin(rel, dir string) bool {
469		return rel == dir || strings.HasPrefix(rel, dir+"/")
470	}
471	
472	// baselineWithin restricts the directory baseline to the walked subtrees,
473	// so reconcileDirectories never mistakes a directory outside them (which
474	// this cycle didn't scan) for one deleted on both sides.
475	func baselineWithin(baseline map[string]struct{}, subtrees []scopedSubtree) map[string]struct{} {
476		out := make(map[string]struct{})
477		for d := range baseline {
478			for _, st := range subtrees {
479				if isWithin(d, st.rel) {
480					out[d] = struct{}{}
481					break
482				}
483			}
484		}
485		return out
486	}
487	
488	// mergeScanResult folds src (a subtree scan of the same root) into dst.
489	func mergeScanResult(dst *fs.ScanResult, src fs.ScanResult) {
490		for k, v := range src.Files {
491			dst.Files[k] = v
492		}
493		for k := range src.Skipped {
494			dst.Skipped[k] = struct{}{}
495			delete(dst.Files, k)
496		}
497		for k := range src.SkippedDirs {
498			dst.SkippedDirs[k] = struct{}{}
499		}
500		for k := range src.Dirs {
501			dst.Dirs[k] = struct{}{}
502		}
503		dst.Issues = append(dst.Issues, src.Issues...)
504	}
505	
506	// RunInit bootstraps first-time setup: creates the local and remote root
507	// directories if missing, and writes the remote canary file (.synclock) if
508	// it isn't already there. It performs no reconciliation.
509	func RunInit(localRoot, remoteRoot string, logger *runtime.Logger) error {
510		// Same guard watch and sync apply: a remote nested in the local root
511		// (or vice versa) would put the canary inside the tree being synced,
512		// and every later `watch` against this pair refuses to start anyway.
513		overlap, err := rootsOverlap(localRoot, remoteRoot)
514		if err != nil {
515			return fmt.Errorf("resolve init roots: %w", err)
516		}
517		if overlap {
518			return fmt.Errorf("local and remote roots must not be the same directory or nested inside one another: %s, %s", localRoot, remoteRoot)
519		}
520		if err := os.MkdirAll(localRoot, 0o755); err != nil {
521			return fmt.Errorf("create local root: %w", err)
522		}
523		if err := os.MkdirAll(remoteRoot, 0o755); err != nil {
524			return fmt.Errorf("create remote root: %w", err)
525		}
526		created, err := runtime.EnsureRemoteCanary(remoteRoot)
527		if err != nil {
528			return err
529		}
530		if created {
531			logger.Printf("created remote canary file in %s", remoteRoot)
532		} else {
533			logger.Printf("remote canary file already present in %s", remoteRoot)
534		}
535		logger.Printf("syncd initialized: local=%s remote=%s", localRoot, remoteRoot)
536		return nil
537	}
538	
539	// scanProgressLogger turns scan progress into log lines so a long-running
540	// scan (e.g. a large tree over a slow SMB mount) is visibly still working
541	// instead of looking identical to a hang until it finishes.
542	func scanProgressLogger(logger *runtime.Logger) fs.ScanPairProgressFunc {
543		return func(side string, scanned int, done bool) {
544			if done {
545				logger.Printf("scan %s: done, %d file(s)", side, scanned)
546				return
547			}
548			logger.Printf("scan %s: %d file(s) so far...", side, scanned)
549		}
550	}
551	
552	// mergeSkipSet builds the reconcile.SkipSet both reconcilers use to suppress
553	// action generation for paths this scan couldn't read, from one or more
554	// fs.ScanResults (typically a local+remote pair) - merging both their exact
555	// Skipped paths and their SkippedDirs, so a directory unreadable on either
556	// side covers its whole subtree via reconcile.SkipSet.Contains regardless of
557	// which side hit the problem.
558	func mergeSkipSet(scans ...fs.ScanResult) reconcile.SkipSet {
559		exact := make(map[string]struct{})
560		dirs := make(map[string]struct{})
561		for _, s := range scans {
562			for k := range s.Skipped {
563				exact[k] = struct{}{}
564			}
565			for k := range s.SkippedDirs {
566				dirs[k] = struct{}{}
567			}
568		}
569		return reconcile.NewSkipSet(exact, dirs)
570	}
571	
572	// logScanIssues records each scan issue from one side (side is "local" or
573	// "remote") at Info level - log file only, never stderr - and, if there were
574	// any, a single aggregated Warn line (which per Logger's contract always
575	// reaches stderr, regardless of --silent) so the condition stays visible to
576	// the operator without flooding stderr/the log file.
577	//
578	// This is the fix for the review's Important 4 finding: RunRobustOnce runs
579	// on every --remote-poll tick (30s by default), and the previous code logged
580	// one Logger.Error per issue - since Task 2 made Error unconditionally reach
581	// both stderr and the log file, a tree with 50 permanently-unreadable
582	// symlinks produced ~100 stderr lines/minute forever, growing the log by
583	// ~17MB/day. Per-path detail is still fully available (in the log file, at
584	// Info), just not re-blasted to stderr every cycle for a condition the
585	// operator often cannot immediately fix. This also fixes the asymmetry the
586	// same finding called out: the old code only ever logged Local.Issues, so a
587	// remote-side (over SMB) read/hash failure was reported to nobody; callers
588	// must invoke this for both sides.
589	func logScanIssues(logger *runtime.Logger, side string, issues []fs.ScanIssue) {
590		for _, issue := range issues {
591			logger.Info("skipping file", map[string]any{
592				"side":   side,
593				"path":   issue.Path,
594				"reason": issue.Reason,
595			})
596		}
597		if len(issues) > 0 {
598			logger.Warn(fmt.Sprintf("skipped %d %s file(s) during scan; see log for per-path detail", len(issues), side), map[string]any{
599				"side":  side,
600				"count": len(issues),
601			})
602		}
603	}
