20	// ErrAborted is returned by SyncOnce when the caller's Confirm callback
21	// declines the run. It is not a failure - the caller (the `syncd sync` CLI
22	// command) treats it as a clean, user-initiated cancellation rather than an
23	// error to report as such.
24	var ErrAborted = errors.New("sync: aborted by user")
25	
26	// SyncOptions configures a single ad-hoc/fast (or --hash/robust) sync job
27	// run by SyncOnce.
28	type SyncOptions struct {
29		Name, Left, Right string
30		// StateKey identifies this job's persisted state (job_state rows for
31		// fast two-way, via stateKey below) independently of its display Name -
32		// cli.runSyncJob derives it from Name plus a hash of the canonicalized
33		// root pair, so two jobs sharing a Name (or one job repointed at a new
34		// pair) never reuse each other's state. Falls back to Name when unset,
35		// so callers that don't need the distinction (tests, direct API use)
36		// can leave it empty.
37		StateKey string
38		Mode     reconcile.FastMode
39		UseHash  bool
40		Assume   bool // --yes: skip interactive confirm
41		DryRun   bool // --dry-run: print the summary and exit without mutating anything or persisting job state. Still acquires the per-job lock (cli.runSyncJob) and opens/creates the state db (SyncOnce below) - deliberate, since this is a read of shared job state, not a mutation; see docs/follow-ups.md #3.
42		Workers  int
43		DBPath   string
44		Confirm  func(summary string) bool // nil => auto-yes; cli passes a pterm confirm
45		Progress execute.ProgressSink      // nil => no progress bar
46		// HighlightPath, if set, styles the left/right root paths in the
47		// confirm/dry-run summary (the CLI passes a terminal color when stdout
48		// is a TTY). nil => plain text.
49		HighlightPath func(string) string
50	}
51	
52	// SyncOnce runs a single fast job (mirror/update/two-way). If opts.UseHash
53	// is true it instead runs the robust three-way (hash-based) engine for this
54	// one job, reusing the same scan/plan/execute/manifest-update shape as
55	// app.Run's always-on loop.
56	func SyncOnce(ctx context.Context, opts SyncOptions) error {
57		if opts.Workers < 1 {
58			opts.Workers = 1
59		}
60	
61		// Opened before prepareRoots (rather than after, as before) so
62		// validateRoots can check for prior two-way job_state - see its own doc
63		// comment and hasPriorTwoWayState for why that ordering matters.
64		sqlDB, err := db.Open(opts.DBPath)
65		if err != nil {
66			return fmt.Errorf("open state db: %w", err)
67		}
68		defer sqlDB.Close()
69	
70		hasPriorState, err := hasPriorTwoWayState(ctx, sqlDB, opts)
71		if err != nil {
72			return fmt.Errorf("check prior job state: %w", err)
73		}
74	
75		if err := prepareRoots(opts, hasPriorState); err != nil {
76			return err
77		}
78	
79		if opts.UseHash {
80			return runRobustOnce(ctx, sqlDB, opts)
81		}
82		return runFastOnce(ctx, sqlDB, opts)
83	}
84	
85	// hasPriorTwoWayState reports whether persisted job_state rows already exist
86	// for opts' state key. Only meaningful for fast two-way (mirror/update/--hash
87	// already require their source to exist unconditionally, regardless of
88	// prior state - see validateRoots), where it decides whether an
89	// auto-created empty root is safe.
90	func hasPriorTwoWayState(ctx context.Context, sqlDB *sql.DB, opts SyncOptions) (bool, error) {
91		if opts.UseHash || opts.Mode != reconcile.FastTwoWay {
92			return false, nil
93		}
94		prev, err := db.NewJobStateRepo(sqlDB).Load(ctx, stateKey(opts))
95		if err != nil {
96			return false, err
97		}
98		return len(prev) > 0, nil
99	}
100	
101	// stateKey returns opts.StateKey if the caller set one, else opts.Name -
102	// SyncOnce itself doesn't require a canonical StateKey (existing tests and
103	// any direct caller can keep using bare Name), but cli.runSyncJob always
104	// sets it, deriving it from the job's canonicalized root pair so two jobs
105	// sharing a Name never collide on persisted job_state (review finding P1
106	// #1, Codex).
107	func stateKey(opts SyncOptions) string {
108		if opts.StateKey != "" {
109			return opts.StateKey
110		}
111		return opts.Name
112	}
113	
114	// prepareRoots ensures both sync roots exist before scanning (ad-hoc jobs
115	// are commonly pointed at a destination that doesn't exist yet - that's the
116	// point of `mirror` - unlike the always-on daemon, which requires --init
117	// first and so can assume both roots are already there) - except for
118	// --dry-run, which must not create anything on disk at all (see
119	// validateRoots/createRoots below for why the two are split).
120	func prepareRoots(opts SyncOptions, hasPriorState bool) error {
121		if err := validateRoots(opts, hasPriorState); err != nil {
122			return err
123		}
124		if opts.DryRun {
125			return nil
126		}
127		return createRoots(opts)
128	}
129	
130	// validateRoots is prepareRoots' data-loss guard, and runs unconditionally
131	// - even for --dry-run, which must report the exact same error as a real
132	// run against a genuinely missing source, not silently treat it as empty.
133	//
134	// It is deliberately mode-aware: mirror/update (fast) and the --hash/robust
135	// path are directional, with opts.Left as the source of truth, so
136	// fabricating an empty source there would be a footgun - FastCompare's
137	// mirror branch (or BuildPlan) would see "everything on the destination is
138	// gone from the source" and emit deletes for the destination's entire
139	// contents, silently wiping it under --yes. For those modes the source
140	// (opts.Left) must already exist.
141	//
142	// two-way (fast) is symmetric and safe to auto-create ONLY when
143	// hasPriorState is false - "a missing side with no prior persisted state
144	// produces copies, not deletes" is true precisely because there is nothing
145	// in job_state for FastCompare to read as "this path used to exist here".
146	// Once job_state DOES have rows for this job (a prior successful sync), that
147	// reasoning breaks: a left root that has vanished entirely (wrong mount
148	// point, accidental deletion, replaced disk - not just one file removed
149	// from within it) would otherwise be silently recreated empty, and
150	// FastCompare's lDeleted branch would read every previously-tracked path as
151	// "deleted locally", emitting a DeleteR for each and wiping right under
152	// --yes (review finding, GLM-5.2). So once hasPriorState is true, two-way
153	// gets the exact same must-already-exist guard as mirror/update, for BOTH
154	// sides.
155	func validateRoots(opts SyncOptions, hasPriorState bool) error {
156		overlap, err := rootsOverlap(opts.Left, opts.Right)
157		if err != nil {
158			return fmt.Errorf("resolve sync roots: %w", err)
159		}
160		if overlap {
161			return fmt.Errorf("left and right sync roots must not be the same directory or nested inside one another: %s, %s", opts.Left, opts.Right)
162		}
163		if !opts.UseHash && opts.Mode == reconcile.FastTwoWay {
164			if !hasPriorState {
165				return nil
166			}
167			if err := requireExistingDir(opts.Left, "left"); err != nil {
168				return err
169			}
170			return requireExistingDir(opts.Right, "right")
171		}
172		return requireExistingDir(opts.Left, "source")
173	}
174	
175	// requireExistingDir errors unless path exists and is a real directory.
176	// os.Lstat, not os.Stat: filepath.WalkDir (fs.ScanTree) Lstats the root
177	// itself, so a symlink there is never followed and never recurses into -
178	// its callback fires once at path==root and returns immediately, producing
179	// a silently EMPTY scan rather than an error. Using Stat here (which
180	// follows symlinks) would let a symlink-to-a-real-directory root pass
181	// validation while still scanning as empty, so mirror/two-way would delete
182	// every file already on the other side.
183	func requireExistingDir(path, label string) error {
184		info, err := os.Lstat(path)
185		if err != nil {
186			if os.IsNotExist(err) {
187				return fmt.Errorf("%s directory does not exist: %s", label, path)
188			}
189			return fmt.Errorf("stat %s directory %s: %w", label, path, err)
190		}
191		if !info.IsDir() {
192			return fmt.Errorf("%s is not a directory: %s", label, path)
193		}
194		return nil
195	}
196	
197	// rootsOverlap reports whether a and b denote the same directory, or one is
198	// nested inside the other - checked unconditionally for every mode
199	// (including two-way, which has no source-must-exist requirement of its
200	// own), since scanning a destination that lives inside its own source scans
201	// the same files twice under different relative-path keys (e.g. --left
202	// /data --right /data/backup: a file under backup/ is keyed "backup/foo"
203	// from the left scan but "foo" from the right scan), so a reconciler sees no
204	// correspondence between them and treats one side's real files as
205	// extraneous on the other - mirror would then delete them.
206	//
207	// Symlinks are resolved via filepath.EvalSymlinks so a and b that merely
208	// alias the same directory through a symlink are also caught; a path that
209	// doesn't exist yet (legitimate for two-way's auto-created roots) is
210	// compared on its cleaned absolute form only, since there is nothing to
211	// resolve.
212	func rootsOverlap(a, b string) (bool, error) {
213		absA, err := filepath.Abs(a)
214		if err != nil {
215			return false, fmt.Errorf("resolve %s: %w", a, err)
216		}
217		absB, err := filepath.Abs(b)
218		if err != nil {
219			return false, fmt.Errorf("resolve %s: %w", b, err)
220		}
221		resolvedA := resolveIfExists(absA)
222		resolvedB := resolveIfExists(absB)
223		return pathContainsOrEquals(resolvedA, resolvedB) || pathContainsOrEquals(resolvedB, resolvedA), nil
224	}
225	
226	// resolveIfExists returns p with symlinks resolved via filepath.EvalSymlinks
227	// when p exists, or p unchanged (already filepath.Abs'd by the caller) when
228	// it doesn't - a path that isn't there yet has nothing to resolve, and that
229	// is not an error condition here (two-way legitimately auto-creates roots).
230	func resolveIfExists(p string) string {
231		if resolved, err := filepath.EvalSymlinks(p); err == nil {
232			return resolved
233		}
234		return p
235	}
236	
237	// pathContainsOrEquals reports whether child is parent itself, or a
238	// descendant of it, after both have already been made absolute (and
239	// symlink-resolved where possible) by the caller.
240	func pathContainsOrEquals(parent, child string) bool {
241		parent = filepath.Clean(parent)
242		child = filepath.Clean(child)
243		if parent == child {
244			return true
245		}
246		rel, err := filepath.Rel(parent, child)
247		if err != nil {
248			return false
249		}
250		return rel != ".." && !strings.HasPrefix(rel, ".."+string(filepath.Separator))
251	}
252	
253	// createRoots creates whichever roots don't exist yet, and is skipped
254	// entirely for --dry-run (which must not create anything on disk - not
255	// even an empty destination directory, since that's still a real mutation
256	// on whatever filesystem opts.Right lives on, including a mounted SMB
257	// share in production).
258	//
259	// mirror/update/--hash only create the destination (opts.Right) - the
260	// source (opts.Left) was already validated to exist by validateRoots and
261	// must never be auto-created, per the data-loss guard. two-way creates
262	// both roots (see validateRoots' doc comment for why that's safe there).
263	func createRoots(opts SyncOptions) error {
264		if !opts.UseHash && opts.Mode == reconcile.FastTwoWay {
265			if err := os.MkdirAll(opts.Left, 0o755); err != nil {
266				return fmt.Errorf("create left root: %w", err)
267			}
268		}
269		if err := os.MkdirAll(opts.Right, 0o755); err != nil {
270			return fmt.Errorf("create right root: %w", err)
271		}
272		return nil
273	}
274	
275	// confirmOrDefault returns opts.Confirm, defaulting to an always-yes
276	// function when nil (per the SyncOptions.Confirm doc: nil => auto-yes).
277	func confirmOrDefault(confirm func(string) bool) func(string) bool {
278		if confirm != nil {
279			return confirm
280		}
281		return func(string) bool { return true }
282	}
283	
284	// runFastOnce executes the size+mtime fast reconciler (mirror/update/two-way).
285	func runFastOnce(ctx context.Context, sqlDB *sql.DB, opts SyncOptions) error {
286		scans, err := scanPairForOpts(ctx, opts, nil, fs.HashNever)
287		if err != nil {
288			return fmt.Errorf("scan: %w", err)
289		}
290	
291		// Surface scan issues the same way the robust path does (RunRobustOnce):
292		// per-path detail at Info (log file only), one aggregated Warn summary
293		// per run - see logScanIssues' doc comment. The fast path has no
294		// standing logger of its own (SyncOptions carries no log path), so build
295		// a throwaway one scoped to this call, same pattern runRobustOnce below
296		// already uses for its own --hash bridge.
297		issueLogger, err := runtime.NewLogger(false, "")
298		if err != nil {
299			return fmt.Errorf("create logger: %w", err)
300		}
301		defer issueLogger.Close()
302		logScanIssues(issueLogger, "local", scans.Local.Issues)
303		logScanIssues(issueLogger, "remote", scans.Remote.Issues)
304	
305		left := toJobFileStates(scans.Local.Files)
306		right := toJobFileStates(scans.Remote.Files)
307		skipped := mergeSkipSet(scans.Local, scans.Remote)
308	
309		repo := db.NewJobStateRepo(sqlDB)
310		var prev map[string]db.JobFileState
311		if opts.Mode == reconcile.FastTwoWay {
312			prev, err = repo.Load(ctx, stateKey(opts))
313			if err != nil {
314				return fmt.Errorf("load job state: %w", err)
315			}
316		}
317	
318		res := reconcile.FastCompare(opts.Mode, left, right, prev, skipped)
319	
320		// --dry-run prints the same summary the interactive confirm would show
321		// and exits before anything is mutated - it must not require --yes (no
322		// Confirm callback is ever invoked), and it must not execute the tasks
323		// or persist two-way's job state, or the next real run would compute
324		// its diff against a baseline that never actually happened.
325		if opts.DryRun {
326			fmt.Println(fastSummary(opts, res.Tasks))
327			return nil
328		}
329	
330		// Nothing to do: report it, but don't ask "continue with the file
331		// transfers?" about zero transfers, or start an empty progress bar.
332		// Two-way state is still persisted below - a first run over two
333		// already-identical trees must still establish its baseline.
334		if len(res.Tasks) == 0 {
335			fmt.Println(fastSummary(opts, res.Tasks))
336		} else {
337			if !opts.Assume {
338				if !confirmOrDefault(opts.Confirm)(fastSummary(opts, res.Tasks)) {
339					return ErrAborted
340				}
341			}
342			if err := execute.RunFastTasks(ctx, opts.Workers, opts.Left, opts.Right, res.Tasks, opts.Progress); err != nil {
343				return fmt.Errorf("run fast tasks: %w", err)
344			}
345		}
346	
347		if opts.Mode == reconcile.FastTwoWay {
348			if err := repo.Replace(ctx, stateKey(opts), res.NewState); err != nil {
349				return fmt.Errorf("persist job state: %w", err)
350			}
351		}
352		return nil
353	}
354	
355	// scanPairForOpts scans opts.Left/opts.Right, exactly via fs.ScanPair,
356	// UNLESS opts.DryRun is set - --dry-run skips createRoots, so a root that
357	// doesn't exist yet is a real possibility here (never true for a
358	// non-dry-run call, since createRoots already ran by the time this is
359	// called), and fs.ScanPair/ScanTree deliberately abort the whole scan if
360	// the ROOT itself is missing (load-bearing: that's how a vanished SMB mount
361	// is distinguished from an empty tree, and internal/fs is owned by another
362	// task - that behavior must not be weakened). So for --dry-run only, this
363	// treats a missing root as an empty tree for the PREVIEW rather than
364	// creating it or failing the scan.
365	func scanPairForOpts(ctx context.Context, opts SyncOptions, manifest map[string]db.ManifestRow, policy fs.HashPolicy) (fs.ScanPairResult, error) {
366		if !opts.DryRun {
367			return fs.ScanPair(ctx, opts.Left, opts.Right, manifest, policy, nil)
368		}
369	
370		// Mirrors fs.ScanPair's own local-root-relative ignore matcher and
371		// validateSMBName (true for local/left, false for remote/right), just
372		// scanning each side in turn instead of concurrently - dry-run preview
373		// is not the hot path.
374		matcher, err := fs.LoadIgnoreMatcher(opts.Left)
375		if err != nil {
376			return fs.ScanPairResult{}, err
377		}
378		local, err := scanRootOrEmpty(ctx, opts.Left, manifest, true, matcher, policy)
379		if err != nil {
380			return fs.ScanPairResult{}, err
381		}
382		remote, err := scanRootOrEmpty(ctx, opts.Right, db.RemoteStatView(manifest), false, matcher, policy)
383		if err != nil {
384			return fs.ScanPairResult{}, err
385		}
386		return fs.ScanPairResult{Local: local, Remote: remote}, nil
387	}
388	
389	// scanRootOrEmpty is fs.ScanTree, except a root that doesn't exist yet
390	// yields an empty ScanResult instead of an error. Used only by
391	// scanPairForOpts's --dry-run path - see its doc comment for why.
392	func scanRootOrEmpty(ctx context.Context, root string, manifest map[string]db.ManifestRow, validateSMBName bool, matcher *fs.IgnoreMatcher, policy fs.HashPolicy) (fs.ScanResult, error) {
393		if _, err := os.Stat(root); err != nil {
394			if os.IsNotExist(err) {
395				return fs.ScanResult{
396					Files:       make(map[string]fs.FileEntry),
397					Skipped:     make(map[string]struct{}),
398					SkippedDirs: make(map[string]struct{}),
399					Dirs:        make(map[string]struct{}),
400				}, nil
401			}
402			return fs.ScanResult{}, fmt.Errorf("stat %s: %w", root, err)
403		}
404		return fs.ScanTree(ctx, root, manifest, validateSMBName, matcher, policy, nil)
405	}
