421	// fastSummary builds the human-readable text shown to opts.Confirm (or
422	// printed directly for --dry-run) before a fast-mode run mutates anything.
423	// It lists the affected paths grouped by task type - not just counts - since
424	// for a destructive mirror run this prompt is the only safety gate, and the
425	// user needs to see WHICH files, not just how many. Destructive types
426	// (DeleteL/DeleteR) are listed first, before the copies/moves.
427	func fastSummary(opts SyncOptions, tasks []reconcile.FastTask) string {
428		var b strings.Builder
429		if len(tasks) == 0 {
430			fmt.Fprintf(&b, "sync %q (%s): no changes", opts.Name, opts.Mode)
431		} else {
432			fmt.Fprintf(&b, "sync %q (%s): %d task(s)", opts.Name, opts.Mode, len(tasks))
433		}
434		leftRole, rightRole := fastRootRoles(opts.Mode)
435		appendRoots(&b, opts, leftRole, rightRole)
436		if len(tasks) == 0 {
437			return b.String()
438		}
439		byType := make(map[reconcile.FastTaskType][]string)
440		for _, t := range tasks {
441			entry := t.RelPath
442			if t.OldRelPath != "" { // moves: show where from
443				entry = t.OldRelPath + " -> " + t.RelPath
444			}
445			byType[t.Type] = append(byType[t.Type], entry)
446		}
447		order := []reconcile.FastTaskType{
448			reconcile.DeleteL, reconcile.DeleteR, // destructive first
449			reconcile.ConflictL2R, reconcile.ConflictR2L,
450			reconcile.CopyL2R, reconcile.CopyR2L,
451			reconcile.MoveL, reconcile.MoveR,
452		}
453		for _, tt := range withUnlisted(order, byType) {
454			appendSummaryGroup(&b, fastTaskLabel(tt), byType[tt])
455		}
456		return b.String()
457	}
