459	// fastTaskLabel is the summary heading for a fast task type; conflict
460	// types spell out that the losing side is kept.
461	func fastTaskLabel(tt reconcile.FastTaskType) string {
462		desc := map[reconcile.FastTaskType]string{
463			reconcile.CopyL2R:     "copy left -> right",
464			reconcile.CopyR2L:     "copy right -> left",
465			reconcile.DeleteL:     "delete from left",
466			reconcile.DeleteR:     "delete from right",
467			reconcile.MoveL:       "move within left",
468			reconcile.MoveR:       "move within right",
469			reconcile.ConflictL2R: "both changed, left newer: copy left -> right, right's version kept as a conflict copy",
470			reconcile.ConflictR2L: "both changed, right newer: copy right -> left, left's version kept as a conflict copy",
471		}[tt]
472		if desc == "" {
473			return string(tt)
474		}
475		return string(tt) + " (" + desc + ")"
476	}
