478	// fastRootRoles names what each root is for in mode, for the summary's
479	// root lines: mirror/update are one-way (left is the source of truth), and
480	// two-way has no direction.
481	func fastRootRoles(mode reconcile.FastMode) (left, right string) {
482		switch mode {
483		case reconcile.FastMirror:
484			return "source", "destination"
485		case reconcile.FastUpdate:
486			return "source", "destination"
487		}
488		return "", ""
489	}
