491	// appendRoots writes the summary's root lines - both roots as absolute
492	// paths, each with its role - so a summary read in a script's output (or a
493	// confirm prompt) says unambiguously which directory "left" and "right"
494	// are. The paths go through opts.HighlightPath when set.
495	func appendRoots(b *strings.Builder, opts SyncOptions, leftRole, rightRole string) {
496		label := func(side, role string) string {
497			if role == "" {
498				return side
499			}
500			return side + " (" + role + ")"
501		}
502		leftLabel, rightLabel := label("left", leftRole), label("right", rightRole)
503		width := max(len(leftLabel), len(rightLabel)) + 1 // +1 for the colon
504		highlight := opts.HighlightPath
505		if highlight == nil {
506			highlight = func(s string) string { return s }
507		}
508		fmt.Fprintf(b, "\n  %-*s %s", width, leftLabel+":", highlight(absOrRaw(opts.Left)))
509		fmt.Fprintf(b, "\n  %-*s %s", width, rightLabel+":", highlight(absOrRaw(opts.Right)))
510	}
511	
512	// absOrRaw returns p made absolute, or p unchanged if that fails - a
513	// relative root in a script is exactly what makes "which one is left?"
514	// hard to answer from its output.
515	func absOrRaw(p string) string {
516		if abs, err := filepath.Abs(p); err == nil {
517			return abs
518		}
519		return p
520	}
521	
522	// withUnlisted returns order followed by every other key of present, sorted,
523	// so a task/action type missing from a summary's fixed display order is
524	// still shown rather than executing without ever appearing in the summary
525	// the user approves (docs/follow-ups.md #22).
526	func withUnlisted[K ~string, V any](order []K, present map[K]V) []K {
527		listed := make(map[K]bool, len(order))
528		for _, k := range order {
529			listed[k] = true
530		}
531		var extra []K
532		for k := range present {
533			if !listed[k] {
534				extra = append(extra, k)
535			}
536		}
537		sort.Slice(extra, func(i, j int) bool { return extra[i] < extra[j] })
538		return append(append([]K(nil), order...), extra...)
539	}
