541	// appendSummaryGroup writes one task/action-type section to b: a "Label: N"
542	// header, then up to summaryPathCap of paths (sorted for deterministic
543	// output), then a "... and N more" tail if there were more than that.
544	// Writes nothing if paths is empty.
545	func appendSummaryGroup(b *strings.Builder, label string, paths []string) {
546		if len(paths) == 0 {
547			return
548		}
549		sort.Strings(paths)
550		fmt.Fprintf(b, "\n  %s: %d", label, len(paths))
551		shown := paths
552		var more int
553		if len(paths) > summaryPathCap {
554			shown = paths[:summaryPathCap]
555			more = len(paths) - summaryPathCap
556		}
557		for _, p := range shown {
558			fmt.Fprintf(b, "\n    %s", p)
559		}
560		if more > 0 {
561			fmt.Fprintf(b, "\n    ... and %d more", more)
562		}
563	}
