565	// runRobustOnce runs the robust, hash-based three-way engine for a single
566	// ad-hoc job (the --hash bridge) by delegating the scan -> plan -> execute
567	// -> manifest-update (+ empty-dir) cycle to the shared app.RunRobustOnce
568	// (see sync_loop.go), so the --hash path benefits from the same empty-dir
569	// create/cleanup and scan-progress logging as the always-on watch loop.
570	//
571	// The interactive confirm-before-mutate step (!opts.Assume) runs INSIDE that
572	// one cycle, via RobustParams.ConfirmPlan, between planning and executing:
573	// the user approves exactly the actions that then execute. (It used to
574	// build a separate preview plan from a second full HashAlways scan - twice
575	// the hashing of both trees, and the plan that actually ran came from the
576	// later scan, so it could include actions the user never saw.) A plan with
577	// no file actions runs without prompting.
578	//
579	// --dry-run still builds its own preview (scanPairForOpts), since it must
580	// tolerate a destination that doesn't exist yet and must never reach
581	// RunRobustOnce at all.
582	//
583	// RunRobustOnce takes a *runtime.Logger, which SyncOptions has no
584	// equivalent of; a non-silent logger (no log file) is constructed here,
585	// which is fine for this ad-hoc case - non-silent Loggers route Printf to
586	// stdout, and Warn/Error always reach stderr regardless of --silent (Task 2)
587	// and regardless of whether a log file is open at all; only Info-level
588	// detail has nowhere to go when there's no log file, since Info is
589	// deliberately never printed to stdout/stderr (see logScanIssues, which
590	// relies on exactly that split: per-path detail at Info, one aggregated
591	// summary at Warn).
592	func runRobustOnce(ctx context.Context, sqlDB *sql.DB, opts SyncOptions) error {
593		repo := db.NewManifestRepo(sqlDB)
594	
595		if opts.DryRun {
596			manifest, err := repo.LoadAll(ctx)
597			if err != nil {
598				return fmt.Errorf("load manifest: %w", err)
599			}
600			scans, err := scanPairForOpts(ctx, opts, manifest, fs.HashAlways)
601			if err != nil {
602				return fmt.Errorf("scan: %w", err)
603			}
604			dirBaseline, err := db.NewDirRepo(sqlDB).LoadAll(ctx)
605			if err != nil {
606				return fmt.Errorf("load dir manifest: %w", err)
607			}
608			skipped := mergeSkipSet(scans.Local, scans.Remote)
609			plan := reconcile.BuildPlan(scans.Local.Files, scans.Remote.Files, manifest, skipped)
610			dirOps := visibleDirOps(planDirectories(scans.Local.Dirs, scans.Remote.Dirs, dirBaseline, skipped))
611			fmt.Println(robustSummary(opts, nonNoOpActions(plan), dirOps...))
612			return nil
613		}
614	
615		var confirmPlan func([]reconcile.Action, []DirOp) bool
616		if !opts.Assume {
617			confirm := confirmOrDefault(opts.Confirm)
618			confirmPlan = func(actions []reconcile.Action, dirOps []DirOp) bool {
619				summary := robustSummary(opts, actions, dirOps...)
620				if len(actions) == 0 && len(dirOps) == 0 {
621					fmt.Println(summary)
622					return true
623				}
624				return confirm(summary)
625			}
626		}
627	
628		logger, err := runtime.NewLogger(false, "")
629		if err != nil {
630			return fmt.Errorf("create logger: %w", err)
631		}
632		defer logger.Close()
633	
634		_, failures, runErr := RunRobustOnce(ctx, RobustParams{
635			LocalRoot:   opts.Left,
636			RemoteRoot:  opts.Right,
637			Workers:     opts.Workers,
638			Repo:        repo,
639			DB:          sqlDB,
640			Logger:      logger,
641			Policy:      fs.HashAlways,
642			ConfirmPlan: confirmPlan,
643		})
644		if errors.Is(runErr, ErrAborted) {
645			return ErrAborted
646		}
647		// A hard failure (manifest LoadAll, ScanPair, or ApplyUpdates) is
648		// reported with this call site's own original per-stage wrapping,
649		// matching this function's pre-RunRobustOnce error text exactly.
650		if hard, ok := runErr.(*robustHardError); ok {
651			return fmt.Errorf("%s: %w", hard.stage, hard.err)
652		}
653		if runErr != nil {
654			return fmt.Errorf("sync run did not complete: %w", runErr)
655		}
656		if failures > 0 {
657			return fmt.Errorf("sync completed with %d failed action(s)", failures)
658		}
659		return nil
660	}
