680	// will change (docs/follow-ups.md #29).
681	func robustSummary(opts SyncOptions, actions []reconcile.Action, dirOps ...DirOp) string {
682		var b strings.Builder
683		if len(actions) == 0 && len(dirOps) == 0 {
