// Package service installs `syncd watch` as a per-user background service:
// a launchd agent on macOS, a systemd user unit on Linux. It only writes
// the service definition and drives launchctl/systemctl; the daemon itself
// is unchanged.
package service

import (
	"fmt"
	"os"
	"os/exec"
	"path/filepath"
	"regexp"
	"strings"
	"time"
)

// Spec describes one service to install.
type Spec struct {
	// Name distinguishes several services on one machine (one per root
	// pair); empty is the default, unnamed service.
	Name string
	// Binary is the absolute path of the syncd executable to run.
	Binary string
	// Args are syncd's arguments ("watch", "--local", ...).
	Args []string
	// Description is shown by systemctl/journalctl.
	Description string
	// LogDir receives the service's stdout/stderr on macOS (launchd has no
	// journal). Unused on Linux, where they go to the user journal.
	LogDir string
}

// Runner runs an external command and returns its combined output.
type Runner func(name string, args ...string) (string, error)

// ExecRunner is the Runner that really runs commands.
func ExecRunner(name string, args ...string) (string, error) {
	out, err := exec.Command(name, args...).CombinedOutput()
	return strings.TrimSpace(string(out)), err
}

// Manager installs, removes and inspects services for one platform.
type Manager struct {
	GOOS string // "darwin" or "linux"
	Home string // the user's home directory
	UID  int
	Run  Runner
}

// Result reports what Install did.
type Result struct {
	Path  string   // the service definition file written
	Notes []string // things the user should know or do next
}

var nameRE = regexp.MustCompile(`^[A-Za-z0-9_-]+$`)

func validateName(name string) error {
	if name != "" && !nameRE.MatchString(name) {
		return fmt.Errorf("invalid service name %q (use letters, digits, - and _)", name)
	}
	return nil
}

// Label is the launchd label for name.
func Label(name string) string {
	if name == "" {
		return "com.syncd.watch"
	}
	return "com.syncd.watch." + name
}

// UnitName is the systemd unit name for name.
func UnitName(name string) string {
	if name == "" {
		return "syncd-watch.service"
	}
	return "syncd-watch-" + name + ".service"
}

// DefinitionPath is where the service definition for name lives.
func (m Manager) DefinitionPath(name string) (string, error) {
	switch m.GOOS {
	case "darwin":
		return filepath.Join(m.Home, "Library", "LaunchAgents", Label(name)+".plist"), nil
	case "linux":
		return filepath.Join(m.Home, ".config", "systemd", "user", UnitName(name)), nil
	}
	return "", fmt.Errorf("installing a service is not supported on %s", m.GOOS)
}

// LogPaths returns the stdout and stderr files of the macOS service name.
func LogPaths(logDir, name string) (stdout, stderr string) {
	base := "service"
	if name != "" {
		base += "-" + name
	}
	return filepath.Join(logDir, base+".out.log"), filepath.Join(logDir, base+".err.log")
}

// Install writes the service definition and (re)starts the service, so
// running it again with different arguments updates a service in place.
func (m Manager) Install(spec Spec) (Result, error) {
	if err := validateName(spec.Name); err != nil {
		return Result{}, err
	}
	path, err := m.DefinitionPath(spec.Name)
	if err != nil {
		return Result{}, err
	}
	var content string
	if m.GOOS == "darwin" {
		if err := os.MkdirAll(spec.LogDir, 0o755); err != nil {
			return Result{}, fmt.Errorf("create log directory: %w", err)
		}
		content = RenderPlist(spec)
	} else {
		content = RenderUnit(spec)
	}
	if err := os.MkdirAll(filepath.Dir(path), 0o755); err != nil {
		return Result{}, fmt.Errorf("create %s: %w", filepath.Dir(path), err)
	}
	if err := os.WriteFile(path, []byte(content), 0o644); err != nil {
		return Result{}, fmt.Errorf("write service definition: %w", err)
	}
	res := Result{Path: path}

	if m.GOOS == "darwin" {
		domain := fmt.Sprintf("gui/%d", m.UID)
		// Unload a previous version first; "not loaded" is the normal case.
		_, _ = m.Run("launchctl", "bootout", domain+"/"+Label(spec.Name))
		if err := m.bootstrap(domain, path); err != nil {
			return res, err
		}
		_, stderr := LogPaths(spec.LogDir, spec.Name)
		res.Notes = append(res.Notes,
			"startup problems are written to "+stderr,
			"if macOS asks whether syncd may access files on a network volume (or a protected folder), allow it; until then the daemon cannot read the share",
		)
		return res, nil
	}

	unit := UnitName(spec.Name)
	for _, args := range [][]string{
		{"--user", "daemon-reload"},
		{"--user", "enable", unit},
		{"--user", "restart", unit},
	} {
		if out, err := m.Run("systemctl", args...); err != nil {
			return res, fmt.Errorf("systemctl %s: %w: %s", strings.Join(args, " "), err, out)
		}
	}
	res.Notes = append(res.Notes, "follow its output with: journalctl --user -u "+unit+" -f")
	if user := os.Getenv("USER"); user != "" {
		if out, err := m.Run("loginctl", "show-user", user, "-p", "Linger", "--value"); err == nil && strings.TrimSpace(out) == "no" {
			res.Notes = append(res.Notes, "the service only runs while you are logged in; to start it at boot and keep it running after logout: sudo loginctl enable-linger "+user)
		}
	}
	return res, nil
}

// bootstrapRetryDelay is indirected for tests.
var bootstrapRetryDelay = 500 * time.Millisecond

// bootstrap loads the plist. launchctl bootout returns before the old
// instance has finished exiting, and a bootstrap issued in that window
// fails ("Input/output error"), so it is retried briefly.
func (m Manager) bootstrap(domain, plist string) error {
	var out string
	var err error
	for attempt := 0; attempt < 10; attempt++ {
		if out, err = m.Run("launchctl", "bootstrap", domain, plist); err == nil {
			return nil
		}
		time.Sleep(bootstrapRetryDelay)
	}
	return fmt.Errorf("launchctl bootstrap %s %s: %w: %s", domain, plist, err, out)
}

// Uninstall stops the service and removes its definition. It reports
// whether there was a definition to remove.
func (m Manager) Uninstall(name string) (bool, error) {
	if err := validateName(name); err != nil {
		return false, err
	}
	path, err := m.DefinitionPath(name)
	if err != nil {
		return false, err
	}
	_, statErr := os.Stat(path)
	installed := statErr == nil

	// Stop it even if the definition is already gone: a loaded service
	// outlives its file. Failure here just means it was not loaded.
	if m.GOOS == "darwin" {
		_, _ = m.Run("launchctl", "bootout", fmt.Sprintf("gui/%d/%s", m.UID, Label(name)))
	} else {
		_, _ = m.Run("systemctl", "--user", "disable", "--now", UnitName(name))
	}
	if err := os.Remove(path); err != nil && !os.IsNotExist(err) {
		return installed, fmt.Errorf("remove service definition: %w", err)
	}
	if m.GOOS == "linux" {
		_, _ = m.Run("systemctl", "--user", "daemon-reload")
	}
	return installed, nil
}

// Status describes the service name in a few lines.
func (m Manager) Status(name string) (string, error) {
	if err := validateName(name); err != nil {
		return "", err
	}
	path, err := m.DefinitionPath(name)
	if err != nil {
		return "", err
	}
	var b strings.Builder
	if _, err := os.Stat(path); err != nil {
		fmt.Fprintf(&b, "not installed (no %s)\n", path)
	} else {
		fmt.Fprintf(&b, "definition: %s\n", path)
	}

	if m.GOOS == "darwin" {
		out, err := m.Run("launchctl", "print", fmt.Sprintf("gui/%d/%s", m.UID, Label(name)))
		if err != nil {
			b.WriteString("state: not loaded\n")
			return b.String(), nil
		}
		for _, key := range []string{"state", "pid", "last exit code"} {
			if v, ok := launchctlField(out, key); ok {
				fmt.Fprintf(&b, "%s: %s\n", key, v)
			}
		}
		return b.String(), nil
	}

	// `show` succeeds for an unknown unit too (LoadState=not-found).
	out, err := m.Run("systemctl", "--user", "show", UnitName(name),
		"-p", "LoadState", "-p", "UnitFileState", "-p", "ActiveState", "-p", "SubState", "-p", "MainPID", "-p", "ExecMainStatus")
	if err != nil {
		return b.String(), fmt.Errorf("systemctl show: %w: %s", err, out)
	}
	props := make(map[string]string)
	for _, line := range strings.Split(out, "\n") {
		if k, v, ok := strings.Cut(strings.TrimSpace(line), "="); ok {
			props[k] = v
		}
	}
	if props["LoadState"] == "not-found" {
		b.WriteString("state: not loaded\n")
		return b.String(), nil
	}
	fmt.Fprintf(&b, "state: %s (%s), %s\n", props["ActiveState"], props["SubState"], props["UnitFileState"])
	if pid := props["MainPID"]; pid != "" && pid != "0" {
		fmt.Fprintf(&b, "pid: %s\n", pid)
	} else {
		fmt.Fprintf(&b, "last exit code: %s\n", props["ExecMainStatus"])
	}
	return b.String(), nil
}

// launchctlField extracts a top-level "key = value" line from `launchctl
// print` output (top-level lines are indented by a single tab).
func launchctlField(out, key string) (string, bool) {
	prefix := "\t" + key + " = "
	for _, line := range strings.Split(out, "\n") {
		if v, ok := strings.CutPrefix(line, prefix); ok {
			return strings.TrimSpace(v), true
		}
	}
	return "", false
}

package service

import (
	"encoding/xml"
	"fmt"
	"strings"
)

// RenderPlist returns the launchd agent definition for spec.
//
// KeepAlive restarts the daemon whenever it exits; ThrottleInterval keeps
// a daemon that cannot start (say, its lock is held) from being relaunched
// more than twice a minute. The daemon is started with --wait-for-remote
// (see cli), so a share that is not mounted yet is waited for in-process
// rather than through that restart loop.
func RenderPlist(spec Spec) string {
	stdout, stderr := LogPaths(spec.LogDir, spec.Name)
	var b strings.Builder
	b.WriteString(`<?xml version="1.0" encoding="UTF-8"?>
<!DOCTYPE plist PUBLIC "-//Apple//DTD PLIST 1.0//EN" "http://www.apple.com/DTDs/PropertyList-1.0.dtd">
<!-- Written by "syncd service install"; rerun it to change, "syncd service uninstall" to remove. -->
<plist version="1.0">
<dict>
  <key>Label</key>
  <string>` + xmlEscape(Label(spec.Name)) + `</string>
  <key>ProgramArguments</key>
  <array>
`)
	for _, arg := range append([]string{spec.Binary}, spec.Args...) {
		fmt.Fprintf(&b, "    <string>%s</string>\n", xmlEscape(arg))
	}
	b.WriteString(`  </array>
  <key>RunAtLoad</key>
  <true/>
  <key>KeepAlive</key>
  <true/>
  <key>ThrottleInterval</key>
  <integer>30</integer>
  <key>StandardOutPath</key>
  <string>` + xmlEscape(stdout) + `</string>
  <key>StandardErrorPath</key>
  <string>` + xmlEscape(stderr) + `</string>
</dict>
</plist>
`)
	return b.String()
}

func xmlEscape(s string) string {
	var b strings.Builder
	_ = xml.EscapeText(&b, []byte(s))
	return b.String()
}

// RenderUnit returns the systemd user unit for spec.
//
// There is deliberately no mount dependency: a user unit cannot order
// itself after a system automount, and the daemon's --wait-for-remote
// covers it (touching the share is also what triggers an automount).
func RenderUnit(spec Spec) string {
	args := make([]string, 0, len(spec.Args)+1)
	for _, arg := range append([]string{spec.Binary}, spec.Args...) {
		args = append(args, systemdQuote(arg))
	}
	desc := strings.NewReplacer("\n", " ", "%", "%%").Replace(spec.Description)
	return `# Written by "syncd service install"; rerun it to change, "syncd service uninstall" to remove.
[Unit]
Description=` + desc + `

[Service]
Type=simple
ExecStart=` + strings.Join(args, " ") + `
Restart=on-failure
RestartSec=10

[Install]
WantedBy=default.target
`
}

// systemdQuote renders one ExecStart argument: specifier (%) and variable
// ($) characters are doubled so systemd passes them through literally, and
// anything but a plain word is double-quoted with C-style escapes.
func systemdQuote(arg string) string {
	plain := arg != ""
	for _, r := range arg {
		if !(r >= 'a' && r <= 'z' || r >= 'A' && r <= 'Z' || r >= '0' && r <= '9' || strings.ContainsRune("/._-=:,+@", r)) {
			plain = false
			break
		}
	}
	if plain {
		return arg
	}
	r := strings.NewReplacer(`\`, `\\`, `"`, `\"`, "%", "%%", "$", "$$", "\n", `\n`, "\t", `\t`)
	return `"` + r.Replace(arg) + `"`
}

package cli

import (
	"fmt"
	"os"
	"path/filepath"
	stdruntime "runtime"

	"github.com/spf13/cobra"
	"github.com/spf13/pflag"

	"syncd/internal/app"
	"syncd/internal/runtime"
	"syncd/internal/service"
)

var (
	serviceOpts watchFlags
	serviceName string
	serviceBin  string
)

var serviceCmd = &cobra.Command{
	Use:   "service",
	Short: "Install, remove or inspect 'syncd watch' as a background service",
	Long: `Run 'syncd watch' as a per-user background service that starts at login
and is restarted if it exits: a launchd agent on macOS
(~/Library/LaunchAgents), a systemd user unit on Linux
(~/.config/systemd/user). No root access is needed.`,
}

var serviceInstallCmd = &cobra.Command{
	Use:   "install",
	Short: "Install (or update) and start the watch service",
	Long: `Install 'syncd watch' as a background service and start it. It takes the
same flags as 'syncd watch'; the service always runs with --silent and
--wait-for-remote, so it waits for the share to be mounted rather than
failing when it starts first.

Running it again replaces the service's settings and restarts it. Use --name
to run more than one service (one per local/remote pair).

Run 'syncd init' for the pair first.`,
	RunE: runServiceInstall,
}

var serviceUninstallCmd = &cobra.Command{
	Use:   "uninstall",
	Short: "Stop and remove the watch service",
	RunE: func(_ *cobra.Command, _ []string) error {
		m, err := newServiceManager()
		if err != nil {
			return err
		}
		installed, err := m.Uninstall(serviceName)
		if err != nil {
			return err
		}
		if !installed {
			fmt.Println("no service was installed")
			return nil
		}
		fmt.Println("service stopped and removed (sync state, logs and trash are kept)")
		return nil
	},
}

var serviceStatusCmd = &cobra.Command{
	Use:   "status",
	Short: "Show whether the watch service is installed and running",
	RunE: func(_ *cobra.Command, _ []string) error {
		m, err := newServiceManager()
		if err != nil {
			return err
		}
		status, err := m.Status(serviceName)
		fmt.Print(status)
		return err
	},
}

func init() {
	addWatchFlags(serviceInstallCmd, &serviceOpts)
	// Always on for a service; not the user's to choose here.
	_ = serviceInstallCmd.Flags().MarkHidden("silent")
	_ = serviceInstallCmd.Flags().MarkHidden("wait-for-remote")
	serviceInstallCmd.Flags().StringVar(&serviceBin, "bin", "", "syncd executable the service runs (default: this one)")

	for _, c := range []*cobra.Command{serviceInstallCmd, serviceUninstallCmd, serviceStatusCmd} {
		c.Flags().StringVar(&serviceName, "name", "", "Service name, to run more than one (letters, digits, - and _)")
		serviceCmd.AddCommand(c)
	}
	rootCmd.AddCommand(serviceCmd)
}

func newServiceManager() (service.Manager, error) {
	home, err := os.UserHomeDir()
	if err != nil {
		return service.Manager{}, fmt.Errorf("resolve home directory: %w", err)
	}
	return service.Manager{GOOS: stdruntime.GOOS, Home: home, UID: os.Getuid(), Run: service.ExecRunner}, nil
}

func runServiceInstall(cmd *cobra.Command, _ []string) error {
	cfg, err := serviceOpts.watchConfig()
	if err != nil {
		return err
	}
	notes, err := checkServiceRoots(cfg)
	if err != nil {
		return err
	}

	bin := serviceBin
	if bin == "" {
		if bin, err = os.Executable(); err != nil {
			return fmt.Errorf("locate the syncd executable (pass --bin): %w", err)
		}
		if resolved, err := filepath.EvalSymlinks(bin); err == nil {
			bin = resolved
		}
	}
	if bin, err = filepath.Abs(bin); err != nil {
		return fmt.Errorf("resolve --bin: %w", err)
	}
	if info, err := os.Stat(bin); err != nil || info.IsDir() {
		return fmt.Errorf("syncd executable not found at %s", bin)
	}

	// The same state directory the daemon will use, for launchd's
	// stdout/stderr files.
	paths, err := runtime.ResolvePaths(runtime.Config{StateDir: absIfSet(cfg.StateDir)})
	if err != nil {
		return err
	}

	m, err := newServiceManager()
	if err != nil {
		return err
	}
	res, err := m.Install(service.Spec{
		Name:        serviceName,
		Binary:      bin,
		Args:        serviceWatchArgs(cmd.Flags(), cfg),
		Description: fmt.Sprintf("syncd watch (%s <-> %s)", cfg.LocalRoot, cfg.RemoteRoot),
		LogDir:      paths.StateDir,
	})
	if res.Path != "" {
		fmt.Println("wrote " + res.Path)
	}
	if err != nil {
		return err
	}
	fmt.Printf("service started: %s <-> %s\n", cfg.LocalRoot, cfg.RemoteRoot)
	for _, note := range append(notes, res.Notes...) {
		fmt.Println("note: " + note)
	}
	return nil
}

// checkServiceRoots catches, at install time, the setup mistakes that would
// otherwise only show up in a background service's log: a local root that
// isn't there, or a mounted share that was never initialized. A share that
// is simply not mounted right now is fine - the daemon waits for it.
func checkServiceRoots(cfg app.WatchConfig) (notes []string, err error) {
	info, err := os.Stat(cfg.LocalRoot)
	if err != nil || !info.IsDir() {
		return nil, fmt.Errorf("--local %s is not an existing directory (run 'syncd init' first)", cfg.LocalRoot)
	}
	if _, err := os.Stat(cfg.RemoteRoot); err != nil {
		return []string{fmt.Sprintf("%s is not available right now; the service will wait for it", cfg.RemoteRoot)}, nil
	}
	if err := runtime.CheckRemoteCanary(cfg.RemoteRoot); err != nil {
		return nil, fmt.Errorf("%w; run 'syncd init --local %s --remote %s' first", err, cfg.LocalRoot, cfg.RemoteRoot)
	}
	return nil, nil
}

// serviceWatchArgs builds the `syncd watch` command line the service runs:
// the two roots, the always-on service flags, then every other flag the
// user actually passed (defaults are left to the daemon, so a later syncd
// that changes a default is not pinned to the old one). Paths are made
// absolute, since a service does not start in the directory it was
// installed from.
func serviceWatchArgs(flags *pflag.FlagSet, cfg app.WatchConfig) []string {
	args := []string{"watch", "--local", cfg.LocalRoot, "--remote", cfg.RemoteRoot, "--silent", "--wait-for-remote"}
	isPath := map[string]bool{"state-dir": true, "db-path": true, "log-path": true, "lock-path": true}
	skip := map[string]bool{"local": true, "remote": true, "silent": true, "wait-for-remote": true, "name": true, "bin": true}
	flags.Visit(func(f *pflag.Flag) {
		if skip[f.Name] {
			return
		}
		value := f.Value.String()
		if isPath[f.Name] {
			value = absIfSet(value)
		}
		args = append(args, "--"+f.Name+"="+value)
	})
	return args
}

func absIfSet(p string) string {
	if p == "" {
		return ""
	}
	if abs, err := filepath.Abs(p); err == nil {
		return abs
	}
	return p
}

package service

import (
	"errors"
	"os"
	"path/filepath"
	"strings"
	"testing"
)

type call struct {
	name string
	args []string
}

func (c call) String() string { return c.name + " " + strings.Join(c.args, " ") }

// recorder is a Runner that records every command and answers from reply.
type recorder struct {
	calls []call
	reply func(c call) (string, error)
}

func (r *recorder) run(name string, args ...string) (string, error) {
	c := call{name, args}
	r.calls = append(r.calls, c)
	if r.reply != nil {
		return r.reply(c)
	}
	return "", nil
}

func (r *recorder) lines() []string {
	out := make([]string, len(r.calls))
	for i, c := range r.calls {
		out[i] = c.String()
	}
	return out
}

func testSpec(logDir string) Spec {
	return Spec{
		Binary:      "/usr/local/bin/syncd",
		Args:        []string{"watch", "--local", "/Users/me/My Projects", "--remote", "/Volumes/dev", "--silent", "--wait-for-remote", "--max-delete=25%"},
		Description: "syncd watch (/Users/me/My Projects <-> /Volumes/dev)",
		LogDir:      logDir,
	}
}

func TestRenderPlist(t *testing.T) {
	spec := testSpec("/Users/me/.local/state/syncd")
	spec.Args = append(spec.Args, "--state-dir=/tmp/a&b<c>")
	got := RenderPlist(spec)
	for _, want := range []string{
		"<string>com.syncd.watch</string>",
		"<string>/usr/local/bin/syncd</string>",
		"<string>/Users/me/My Projects</string>", // one argument, space and all
		"<string>--state-dir=/tmp/a&amp;b&lt;c&gt;</string>",
		"<key>KeepAlive</key>\n  <true/>",
		"<string>/Users/me/.local/state/syncd/service.err.log</string>",
	} {
		if !strings.Contains(got, want) {
			t.Errorf("plist is missing %q:\n%s", want, got)
		}
	}
	spec.Name = "music"
	if got := RenderPlist(spec); !strings.Contains(got, "<string>com.syncd.watch.music</string>") || !strings.Contains(got, "service-music.out.log") {
		t.Errorf("named plist:\n%s", got)
	}
}

func TestRenderUnit(t *testing.T) {
	spec := testSpec("")
	got := RenderUnit(spec)
	wantExec := `ExecStart=/usr/local/bin/syncd watch --local "/Users/me/My Projects" --remote /Volumes/dev --silent --wait-for-remote "--max-delete=25%%"`
	if !strings.Contains(got, wantExec+"\n") {
		t.Errorf("unit ExecStart, want:\n%s\ngot:\n%s", wantExec, got)
	}
	for _, want := range []string{"Restart=on-failure", "WantedBy=default.target", "Description=syncd watch (/Users/me/My Projects <-> /Volumes/dev)"} {
		if !strings.Contains(got, want) {
			t.Errorf("unit is missing %q:\n%s", want, got)
		}
	}
}

func TestSystemdQuote(t *testing.T) {
	for in, want := range map[string]string{
		"/mnt/dev":         "/mnt/dev",
		"--workers=4":      "--workers=4",
		"":                 `""`,
		"a b":              `"a b"`,
		`say "hi"`:         `"say \"hi\""`,
		`back\slash`:       `"back\\slash"`,
		"$HOME/100%":       `"$$HOME/100%%"`,
		"semi;colon":       `"semi;colon"`,
		"/srv/naïve/path":  `"/srv/naïve/path"`,
		"--max-delete=50%": `"--max-delete=50%%"`,
	} {
		if got := systemdQuote(in); got != want {
			t.Errorf("systemdQuote(%q) = %s, want %s", in, got, want)
		}
	}
}

func TestInstallDarwin(t *testing.T) {
	prev := bootstrapRetryDelay
	bootstrapRetryDelay = 0
	t.Cleanup(func() { bootstrapRetryDelay = prev })

	home := t.TempDir()
	logDir := filepath.Join(home, "state")
	// The first bootstrap lands while the old instance is still exiting.
	bootstraps := 0
	rec := &recorder{reply: func(c call) (string, error) {
		if c.args[0] == "bootstrap" {
			if bootstraps++; bootstraps == 1 {
				return "Bootstrap failed: 5: Input/output error", errors.New("exit status 5")
			}
		}
		return "", nil
	}}
	m := Manager{GOOS: "darwin", Home: home, UID: 501, Run: rec.run}

	res, err := m.Install(testSpec(logDir))
	if err != nil {
		t.Fatal(err)
	}
	plist := filepath.Join(home, "Library", "LaunchAgents", "com.syncd.watch.plist")
	if res.Path != plist {
		t.Fatalf("path = %s, want %s", res.Path, plist)
	}
	if b, err := os.ReadFile(plist); err != nil || !strings.Contains(string(b), "com.syncd.watch") {
		t.Fatalf("plist not written: %v", err)
	}
	if _, err := os.Stat(logDir); err != nil {
		t.Fatalf("log dir not created: %v", err)
	}
	want := []string{
		"launchctl bootout gui/501/com.syncd.watch",
		"launchctl bootstrap gui/501 " + plist,
		"launchctl bootstrap gui/501 " + plist,
	}
	if got := rec.lines(); strings.Join(got, "\n") != strings.Join(want, "\n") {
		t.Fatalf("commands:\n%s\nwant:\n%s", strings.Join(got, "\n"), strings.Join(want, "\n"))
	}
}

func TestInstallLinux(t *testing.T) {
	t.Setenv("USER", "me")
	home := t.TempDir()
	rec := &recorder{reply: func(c call) (string, error) {
		if c.name == "loginctl" {
			return "no\n", nil
		}
		return "", nil
	}}
	m := Manager{GOOS: "linux", Home: home, UID: 1000, Run: rec.run}
	spec := testSpec("")
	spec.Name = "dev"

	res, err := m.Install(spec)
	if err != nil {
		t.Fatal(err)
	}
	unit := filepath.Join(home, ".config", "systemd", "user", "syncd-watch-dev.service")
	if res.Path != unit {
		t.Fatalf("path = %s, want %s", res.Path, unit)
	}
	if _, err := os.Stat(unit); err != nil {
		t.Fatalf("unit not written: %v", err)
	}
	want := []string{
		"systemctl --user daemon-reload",
		"systemctl --user enable syncd-watch-dev.service",
		"systemctl --user restart syncd-watch-dev.service",
		"loginctl show-user me -p Linger --value",
	}
	if got := rec.lines(); strings.Join(got, "\n") != strings.Join(want, "\n") {
		t.Fatalf("commands:\n%s\nwant:\n%s", strings.Join(got, "\n"), strings.Join(want, "\n"))
	}
	if notes := strings.Join(res.Notes, "\n"); !strings.Contains(notes, "enable-linger me") {
		t.Errorf("no linger hint in notes:\n%s", notes)
	}
}

func TestInstallLinuxReportsSystemctlFailure(t *testing.T) {
	rec := &recorder{reply: func(c call) (string, error) {
		if c.name == "systemctl" && c.args[1] == "enable" {
			return "Failed to connect to bus", errors.New("exit status 1")
		}
		return "", nil
	}}
	m := Manager{GOOS: "linux", Home: t.TempDir(), Run: rec.run}
	_, err := m.Install(testSpec(""))
	if err == nil || !strings.Contains(err.Error(), "Failed to connect to bus") {
		t.Fatalf("got %v, want the systemctl failure", err)
	}
}

func TestUninstall(t *testing.T) {
	for _, goos := range []string{"darwin", "linux"} {
		t.Run(goos, func(t *testing.T) {
			prev := bootstrapRetryDelay
			bootstrapRetryDelay = 0
			t.Cleanup(func() { bootstrapRetryDelay = prev })

			home := t.TempDir()
			rec := &recorder{}
			m := Manager{GOOS: goos, Home: home, UID: 501, Run: rec.run}
			res, err := m.Install(testSpec(filepath.Join(home, "state")))
			if err != nil {
				t.Fatal(err)
			}

			rec.calls = nil
			installed, err := m.Uninstall("")
			if err != nil || !installed {
				t.Fatalf("Uninstall: installed=%v err=%v", installed, err)
			}
			if _, err := os.Stat(res.Path); !os.IsNotExist(err) {
				t.Fatal("definition was not removed")
			}
			first := rec.lines()[0]
			wantFirst := map[string]string{
				"darwin": "launchctl bootout gui/501/com.syncd.watch",
				"linux":  "systemctl --user disable --now syncd-watch.service",
			}[goos]
			if first != wantFirst {
				t.Fatalf("first command %q, want %q", first, wantFirst)
			}

			installed, err = m.Uninstall("")
			if err != nil || installed {
				t.Fatalf("second Uninstall: installed=%v err=%v", installed, err)
			}
		})
	}
}

func TestStatus(t *testing.T) {
	home := t.TempDir()

	darwin := Manager{GOOS: "darwin", Home: home, UID: 501, Run: func(string, ...string) (string, error) {
		return "gui/501/com.syncd.watch = {\n\tactive count = 1\n\tstate = running\n\n\tprogram = /x/syncd\n\tpid = 4242\n\tsockets = {\n\t\tstate = nested\n\t}\n}", nil
	}}
	got, err := darwin.Status("")
	if err != nil {
		t.Fatal(err)
	}
	if !strings.Contains(got, "not installed") || !strings.Contains(got, "state: running\n") || !strings.Contains(got, "pid: 4242\n") {
		t.Errorf("darwin status:\n%s", got)
	}

	notLoaded := Manager{GOOS: "darwin", Home: home, UID: 501, Run: func(string, ...string) (string, error) {
		return "Could not find service", errors.New("exit status 113")
	}}
	if got, err := notLoaded.Status(""); err != nil || !strings.Contains(got, "state: not loaded") {
		t.Errorf("darwin not loaded: %q, %v", got, err)
	}

	linux := Manager{GOOS: "linux", Home: home, Run: func(string, ...string) (string, error) {
		return "LoadState=loaded\nUnitFileState=enabled\nActiveState=active\nSubState=running\nMainPID=777\nExecMainStatus=0", nil
	}}
	if got, err := linux.Status(""); err != nil || !strings.Contains(got, "state: active (running), enabled\n") || !strings.Contains(got, "pid: 777\n") {
		t.Errorf("linux status: %q, %v", got, err)
	}

	missing := Manager{GOOS: "linux", Home: home, Run: func(string, ...string) (string, error) {
		return "LoadState=not-found\nActiveState=inactive\nMainPID=0", nil
	}}
	if got, err := missing.Status(""); err != nil || !strings.Contains(got, "state: not loaded") {
		t.Errorf("linux not loaded: %q, %v", got, err)
	}
}

func TestRejectsBadNameAndPlatform(t *testing.T) {
	m := Manager{GOOS: "darwin", Home: t.TempDir(), Run: (&recorder{}).run}
	spec := testSpec(t.TempDir())
	spec.Name = "../evil"
	if _, err := m.Install(spec); err == nil {
		t.Error("accepted a service name with path characters")
	}
	if _, err := m.Uninstall("a b"); err == nil {
		t.Error("Uninstall accepted a bad name")
	}
	win := Manager{GOOS: "windows", Home: t.TempDir(), Run: (&recorder{}).run}
	if _, err := win.Install(testSpec(t.TempDir())); err == nil {
		t.Error("Install succeeded on an unsupported platform")
	}
}

